  ('cartagena-colombia', '10S', 'Cartagena & Colombia''s Caribbean Coast', 'Colombia', 'Walled colonial casas and Caribbean nights', 'live', 'verified', 'venice', 'Colombia''s Caribbean Coast', '{"romance","tropical","culture"}', '{"tropical"}', '{"essential","premier","luxury","ultra"}', null, null, '{"key_facts":["Cartagena''s Ciudad Amurallada (walled old city + fortifications) is the anchor; Castillo San Felipe is the largest Spanish fort in South America; most visitors need 3–4 days.","Islas del Rosario + Barú (Playa Blanca) — ~1hr speedboat to Corales del Rosario National Park, reef snorkel, beach lunch.","Getsemaní — best street art on the coast + Plaza de la Trinidad salsa nights, just outside the walls.","Santa Marta + Tayrona NP protect 150 km² where the Sierra Nevada meets the sea; Cabo San Juan is the iconic cove.","Barranquilla Carnival — UNESCO Intangible Heritage, largest carnival outside Brazil; 2026 dates 14–17 February."],"safety":{"emergency":"123","hospital":"Cartagena private hospitals (stabilization); serious cases route to Bogotá or US medical evacuation","book_enabled":true,"bin":"BOOK WITH WARNING","risk_codes":["C","T","U","K","N"],"risk_code_meanings":{"C":"Crime — violent crime (murder, assault, robbery), drugging (scopolamine), extortion, express kidnapping occur throughout Colombia incl. cities","T":"Terrorism — attacks possible with little/no warning; car bombs, grenades, IEDs, drones","U":"Unrest — demonstrations can shut roads and turn violent","K":"Kidnapping or Hostage-Taking — kidnapping-for-ransom reported","N":"Natural Disaster — volcano, earthquake, landslide"},"named_danger":["Arauca","Cauca excl Popayán","Valle del Cauca excl Cali","Norte de Santander","Venezuela border ~10km"],"cartagena_in_named_danger":false,"consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for Colombia (level + reason + named-danger areas + complete ''If you decide to travel'' guidance, pulled live) + traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"},"air_access_verified":"CTG (Rafael Núñez Intl) — direct international incl. Miami (AA, Avianca) and New York JFK (JetBlue year-round, Avianca seasonal)","water":"bottled","vaccinations":"yellow fever recommended for Tayrona/jungle/Sierra Nevada; dengue present on coast; check CDC","scopolamine_caution":"''devil''s breath''/burundanga drugging — colourless/tasteless; never accept drinks/food/tabs from strangers; dating-app method documented in Cartagena"},"timing":{"peak":"Dec–Mar/Apr (dry); true peak mid-Dec → mid/late-Jan","inflection_curve_start":"early December","fire_date":"mid-to-late November (peak); ~late-January (Barranquilla Carnival)","event_peaks":[{"event":"Barranquilla Carnival","dates_2026":"14–17 February","note":"UNESCO; largest carnival outside Brazil; Barranquilla rooms sell out/price hard"},{"event":"Independence Day (Cartagena)","dates":"November 11","note":"coastal rates +30–40% Nov 9–12"},{"event":"Christmas–New Year","dates":"Dec 20–31","note":"maximum annual congestion"}],"off_season_fill":"Aug–Nov (rates ~half of peak); Jul–Aug veranillo del Niño = best weather-to-cost"},"jewels":[{"name":"Walled Old City + rampart sunset (Café del Mar)","si_tag":"romance","tier":"premier","source":"https://www.lonelyplanet.com/articles/top-things-to-do-in-cartagena-colombia","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"cobbled lanes, Plaza Santo Domingo, and a sunset walk on the coral-stone ramparts","si":"romance","blurb":"cobbled lanes, Plaza Santo Domingo, and a sunset walk on the coral-stone ramparts","when":"Dec–Mar/Apr","commission":"hotel + city-tour affiliate; wedding via DMC/villa"},{"name":"Walled-city colonial-mansion buyout wedding","si_tag":"romance","tier":"premier","source":"https://cartagenadreams.com/explore-cartagena/old-city/unesco-walled-city-colonial-mansion-rental-groups-your-complete-guide-to-cartagena/","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"take over a restored 17th–18th-c. casa for ceremony + dinners + party","si":"romance","blurb":"take over a restored 17th–18th-c. casa for ceremony + dinners + party","when":"Dec–Mar/Apr","commission":"MoR villa + wedding DMC ~10–20% land"},{"name":"Rosario private-island wedding (yacht/speedboat)","si_tag":"romance","tier":"ultra","source":"https://two.travel/planning-your-wedding-in-cartagena-colombia/","si":"romance","commission":"DMC + island villa MoR"},{"name":"Islas del Rosario + Barú (Playa Blanca)","si_tag":"tropical","tier":"essential","source":"https://www.getyourguide.com/cartagena-l362/cartagena-rosario-islands-and-playa-blanca-excursion-with-snorkeling-or-aquarium-t934710/","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"reef snorkel in Corales del Rosario NP, beach-club lunch, hammocks on Playa Blanca","si":"tropical","blurb":"reef snorkel in Corales del Rosario NP, beach-club lunch, hammocks on Playa Blanca","when":"Dec–Mar/Apr","commission":"GetYourGuide/Viator affiliate; island villa MoR"},{"name":"Cabo San Juan, Tayrona NP","si_tag":"tropical","tier":"essential","source":"https://mytriptocolombia.com/visit-parc-tayrona/","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"Dec–Mar/Apr","commission":"Santa Marta DMC + park fee pass-through"},{"name":"Palomino river-tube + beach","si_tag":"tropical","tier":"essential","source":"https://smallgirlbigbackpack.com/how-to-get-to-tayrona-national-park/","si":"tropical","commission":"coast DMC + boutique-lodge affiliate"},{"name":"Getsemaní (street art, Plaza de la Trinidad, Café Havana)","si_tag":"culture","tier":"essential","source":"https://www.cartagenaexplorer.com/getsemani-guide/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"walking-tour affiliate + boutique lodging"},{"name":"Castillo San Felipe de Barajas","si_tag":"culture","tier":"essential","source":"https://mycartagenatrip.com/things-to-do-in-cartagena/","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the largest Spanish fort in South America, on a hill over the city","si":"culture","blurb":"the largest Spanish fort in South America, on a hill over the city","when":"Dec–Mar/Apr","commission":"city-tour affiliate"},{"name":"Minca (coffee/cloud forest, Sierra Nevada)","si_tag":"culture","tier":"essential","source":"https://mytriptocolombia.com/visit-parc-tayrona/","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dec–Mar/Apr","commission":"Santa Marta DMC + eco-lodge affiliate"},{"name":"Ciudad Perdida (Teyuna) 4-day trek","si_tag":"culture","tier":"premier","source":"https://www.kimkim.com/c/the-lost-city-tayrona-park-adventure-10-days","hook":"4-day guided-only trek to pre-Columbian ruins in the Sierra Nevada","si":"culture","blurb":"4-day guided-only trek to pre-Columbian ruins in the Sierra Nevada","commission":"licensed-operator DMC (mandatory)"},{"name":"Barranquilla Carnival","si_tag":"culture","tier":"premier","source":"https://ich.unesco.org/en/RL/carnival-of-barranquilla-00051","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"UNESCO Masterpiece of Intangible Heritage, largest carnival outside Brazil; 2026 dates 14–17 Feb","si":"culture","blurb":"UNESCO Masterpiece of Intangible Heritage, largest carnival outside Brazil; 2026 dates 14–17 Feb","when":"Dec–Mar/Apr","commission":"event DMC + Barranquilla hotel affiliate (fire ~late-Jan)"},{"name":"Mompox (UNESCO colonial river town)","si_tag":"culture","tier":"premier","source":"https://en.wikipedia.org/wiki/Barranquilla_Carnival","timing":"Dec–Mar/Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dec–Mar/Apr","commission":"specialist heritage DMC + boutique lodging"}],"faq":[{"q":"How much does a walled-city wedding in Cartagena cost?","a":"A private-villa wedding for 40–60 guests starts around USD $40,000, including a 2–3-night buyout of a restored colonial casa with pool, rooftop, chef, butler and security. Cartagena''s wedding DMCs assemble venue, villa, catering and logistics as the agent-of-record (~10–20% land).","source":"cartagenadreams.com, 2026-07-07","si_tag":"romance"},{"q":"How do you get to the Rosario Islands and Playa Blanca from Cartagena?","a":"By speedboat — about 1 hour offshore to the Corales del Rosario y San Bernardo National Park for reef snorkeling and a beach-club lunch on Playa Blanca (Barú). Book a licensed day-tour; the ~1-hr open-water return chops up in the windy Dec–Apr season, so tours often head back earlier.","source":"tomplanmytrip.com, 2026-07-07","si_tag":"tropical"},{"q":"What are the must-do sights in Cartagena?","a":"The walled Ciudad Amurallada is the anchor — most visitors need 3–4 days — with Castillo San Felipe de Barajas, the largest Spanish fort in South America, and Getsemaní''s street art and Plaza de la Trinidad salsa nights just outside the walls.","source":"mycartagenatrip.com, 2026-07-07","si_tag":"culture"},{"q":"What''s the real risk to plan for in Cartagena?","a":"Scopolamine (\"devil''s breath\") drugging is the headline traveler risk — colourless and tasteless, slipped into drinks or offered items to incapacitate and rob. The US Embassy singled out Cartagena (with Medellín and Bogotá) as a hotspot, often via dating apps. Never accept drinks, food or tabs from strangers, and travel during daylight.","source":"financecolombia.com, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Cartagena & Colombia''s Caribbean Coast — Walled-City Weddings, Rosario Islands & Tayrona | TravelWell.World","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"es-CO","long_tail_en":["things to do in Cartagena Colombia","Cartagena walled city weddings","Rosario Islands day trip from Cartagena","Tayrona National Park Cabo San Juan guide","is Cartagena safe 2026","Cartagena luxury colonial hotels"],"local_keywords":["qué hacer en Cartagena","Islas del Rosario tour","Ciudad Amurallada Cartagena","bodas Cartagena","Parque Tayrona Cabo San Juan","hoteles de lujo Cartagena"],"hreflang":["en","es-CO"]},"booking":null,"si_checklist_25":null,"sis_present":["romance","tropical","culture"],"ultra":[{"name":"Sofitel Legend Santa Clara","type":"17th-c. former monastery, walled city — prestige address","routing":"Fora/Virtuoso preferred","tier":"ultra"},{"name":"Casa Pestagua","type":"18th-c. palace, Relais & Châteaux, Two MICHELIN Keys 2025","routing":"Fora/Virtuoso preferred","tier":"ultra"},{"name":"Casa San Agustín","type":"11-key colonial mansion, Leading Hotels of the World","routing":"Fora/Virtuoso preferred","tier":"ultra"},{"name":"Hotel Charleston Santa Teresa","type":"grande-dame walled-city luxury","routing":"preferred-partner + host","tier":"luxury→ultra"},{"name":"Tcherassi Hotel + Spa","type":"designer boutique, restored colonial house","routing":"preferred-partner + host","tier":"luxury"},{"name":"Blue Apple Beach (Barú)","type":"design beach club + villa, Barú island","routing":"villa/MoR + host","tier":"ultra"},{"name":"Walled-city private villas","type":"full colonial-house buyouts, chef/butler/security","routing":"MoR villa + wedding DMC","tier":"ultra"}],"source_verified":null,"hero":{"query":"Cartagena & Colombia''s Caribbean Coast, Colombia"},"geo":{"lat":10.391,"lng":-75.4794}}'::jsonb, 2),
  ('akumal-mexico', '10S', 'Akumal', 'Mexico', 'Turtle bay, cenotes and reef', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"diveglobal","ocean","culture"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":["Akumal means ''place of the turtles'' in Maya; the bay''s seagrass beds feed wild green sea turtles.","A certified guide and life jacket are mandatory to enter the turtle-snorkel area.","No touching turtles (federal offense); keep 3 m distance, 2 min per turtle, biodegradable sunscreen or rashguard only.","Turtle sightings permitted 8am-5pm; sessions cap at ~55 minutes; no fins, no diving on the circuit.","Cenote and reef diving are easily reached, making Akumal a serene dive base."],"safety":{"emergency":"911","hospital":"Nearest trauma: Hospiten Riviera Maya, Playa del Carmen (+52 984 159 2200), ~25 min north; local clinics stabilize/transfer; major trauma to Cancún","advisory_level":"L2","malaria":"none in tourist Quintana Roo","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dec-Apr (dry season; highest rates, biggest crowds)","shoulder":"May-Jun & Nov (~30-40% off, good weather)","green":"Jun-mid-Oct (hurricane/low; cheapest)","turtle_season":"green turtles graze year-round; snorkel 8am-5pm, <=55-min sessions; nesting ~May-Oct overlaps green/sargassum months","sargassum_window":"Apr-Aug (Jun-Jul peak); Akumal affected (seagrass bay, naturally weedy)","booking_window_lead_time":"peak 3-4 months (villa stock finite, book earlier); shoulder 4-6 months","holiday_event_peaks":["Christmas/New Year","Spring Break (Mar)","Semana Santa"],"fill_the_beds":"sargassum/green months lead with Yal-Ku Lagoon, cenote dives, reef dives, Tulum-ruin loops, turtle morning at opening","campaign_start_trigger":"peak campaigns open Aug-Sep; shoulder ~3-4 months out; turtle-nesting off-peak push into green season"},"jewels":[{"name":"Guided Akumal Bay turtle snorkel","si_tag":"Ocean Adventures","status":"future","tier":"essential","hook":"Certified-guide snorkel over seagrass to see wild green turtles — no touch, low impact.","bookable_category":"guided snorkel tour","source":"https://absolute-adventure-mexico.com/snorkeling/akumal-bay-regulation-swim-with-the-turtles/","si":"ocean","blurb":"Certified-guide snorkel over seagrass to see wild green turtles — no touch, low impact.","commission":"Amstar 12% / affiliate; bay + guide fees pass-through"},{"name":"Yal-Ku Lagoon snorkel","si_tag":"Ocean Adventures","status":"future","tier":"essential","hook":"Calm brackish lagoon where cenote freshwater meets the sea, rich in fish.","bookable_category":"snorkel add-on","source":"https://alohawanderers.com/puerto-aventuras-what-to-know-before-visiting-this-riviera-maya-gem/","si":"ocean","blurb":"Calm brackish lagoon where cenote freshwater meets the sea, rich in fish.","commission":"affiliate 4-8%; entry pass-through"},{"name":"Akumal-area cenote cavern dive","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Guided cavern dives inland pair the turtle bay with cave country.","bookable_category":"cenote cavern dive (guide required)","source":"https://alohawanderers.com/puerto-aventuras-what-to-know-before-visiting-this-riviera-maya-gem/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Guided cavern dives inland pair the turtle bay with cave country.","when":"Dec-Apr","commission":"DMC 12% / affiliate 4-8%"},{"name":"Akumal reef dive","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Shallow near-shore reef dives with easy multi-dive days.","bookable_category":"reef dive","source":"https://www.prodiveinternational.com/diving/mexico/puerto-aventuras/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Shallow near-shore reef dives with easy multi-dive days.","when":"Dec-Apr","commission":"dive-operator affiliate / DMC 12%"},{"name":"Tulum ruins + turtle-bay combo day","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Cliff-top Maya ruins paired with an Akumal turtle morning.","bookable_category":"guided combo excursion","source":"https://www.embracethejourneytravel.com/agent-portal/vendor-list/amstar/","si":"culture","blurb":"Cliff-top Maya ruins paired with an Akumal turtle morning.","commission":"Amstar 12%; ruin/bay entry pass-through"}],"faq":[{"q":"What''s the real risk to plan for in Akumal?","a":"Sargassum, water, mosquitoes and hurricanes — not violent crime. 2026 is tracking a record sargassum year, with Akumal affected Apr–Aug (Jun–Jul peak) because the bay is seagrass habitat and naturally weedy by design; drink bottled/purified water only, use repellent for dengue (peak May–November, no malaria), and note hurricane season runs June–November.","source":"deeparrival.com / cdc.gov, 2026-07-04","si_tag":"safety"},{"q":"Can you swim with wild sea turtles in Akumal, and when''s best?","a":"Yes — it is the whole reason to come, and green turtles graze the bay''s seagrass year-round. Go at 8am opening for the calmest water and fewest boats; snorkeling is permitted only 8am–5pm in sessions capped at ~55 minutes, always with a certified guide over the seagrass beds.","source":"absolute-adventure-mexico.com, 2026-07-04","si_tag":"ocean"},{"q":"Can I dive cenotes and reef from Akumal?","a":"Yes — Akumal makes a serene dive base for both. Guided cenote cavern dives sit just inland (Cenote Azul corridor) and shallow reef dives are close to shore; cavern diving requires a certified cave/cavern guide and stays in the daylight zone. Observe no-fly of 18h single / 24h repetitive; the nearest chamber is ~25 min north in Playa del Carmen.","source":"sssnetwork.com / alohawanderers.com, 2026-07-04","si_tag":"diveglobal"},{"q":"Is Akumal good for a honeymoon?","a":"Yes, if you want quiet and private over resort buzz. Akumal is villa-driven — beachfront villas with private pools and chef service, plus the wider luxury tier at ~US$400–600+/night in March — and it is calmer and more purposeful than Playa or Tulum. For branded ultra, Rosewood/Banyan Tree at Mayakoba sit ~35–40 min north with an easy turtle-morning day trip.","source":"machupicchu.org / rentalescapes.com, 2026-07-04","si_tag":"romance"},{"q":"When is the best time to visit Akumal, and when is it cheapest?","a":"Nov–March is the best weather window; the cheapest is the green season, June–mid-October. Peak Dec–Apr brings the best conditions and highest rates; May–June and November shoulders run ~30–40% off with thinner crowds; the green season is hot, rainy and cheapest but carries hurricane exposure (Jun–Nov).","source":"machupicchu.org / travelswithelle.com, 2026-07-04","si_tag":"tropical"},{"q":"Can I visit Maya ruins from Akumal?","a":"Yes — Akumal pairs a turtle morning with cliff-top Maya ruins in a single day. Tulum''s ruins are a short drive south and Cobá is inland; a common loop is ruins at 8–10am then the turtle bay after, bookable as a guided combo excursion.","source":"embracethejourneytravel.com, 2026-07-04","si_tag":"culture"}],"seo":{"meta_title":"Akumal Travel Guide 2026 — Swim with Sea Turtles Responsibly | TravelWell.World","meta_description":"Plan Akumal, ''place of the turtles'': guided no-touch turtle snorkeling rules, cenote & reef diving, straight 2026 sargassum, Level 2 safety and nearest dive-chamber contacts.","slug":"akumal-mexico","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04","search_language":["en","es-MX"],"local_keywords":["nadar con tortugas en Akumal","reglas nadar con tortugas Akumal 2026","snorkel en Akumal","buceo en cenotes Akumal","mejor época para ver tortugas en Akumal","sargazo Akumal 2026","Laguna Yal-Ku Akumal","villas frente al mar Akumal"],"hreflang":["en","es-MX"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"diveglobal","status":"future"},{"si":"ocean","status":"future"},{"si":"culture","status":"future"}],"ultra":[{"name":"Akumal beachfront luxury villas","price_tier":"ultra","virtuoso":false,"earning":"on application / host or luxury-DMC villa AOR","mor_posture":true,"note":"no branded ultra hotel in-village; top villa tier","source":"https://www.rentalescapes.com/rentals/luxury-vacation-rentals-mexico/riviera-maya/akumal"},{"name":"Rosewood Mayakoba (~35-40 min north)","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"note":"nearest true ultra hotel","source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Banyan Tree / Andaz-Alila Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"La Casa de la Playa (Grupo Xcaret)","price_tier":"ultra","virtuoso":true,"earning":"15% via Xcaret Agents Pro OR host-Virtuoso ($100 credit)","mor_posture":true,"source":"https://www.virtuoso.com/hotels/16561922/la-casa-de-la-playa"}],"source_verified":"2026-07-04","hero":{"query":"Akumal, Mexico"},"geo":{"lat":20.3958,"lng":-87.3153}}'::jsonb, 3),
  ('ambergris-caye-belize', '10S', 'Ambergris Caye / San Pedro', 'Belize', 'Ambergris Caye Belize', 'live', 'verified', 'tropicalBeach', 'Belize', '{"tropical","liveaboard","romance","expedition"}', '{"tropical"}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Belize''s largest island and #1 tourism engine; runs parallel to the UNESCO Belize Barrier Reef, ~35 mi NE of Belize City.","Hol Chan Marine Reserve (est. 1987, ~4 mi south of San Pedro) protects ~18 km2 with 160+ fish species; Shark Ray Alley added 1999.","Belize''s national recompression capability is on-island: SSS hyperbaric chamber (since 1989) + DAN-affiliated Belize Chamber Project (2015), both 24/7.","Air access via BZE Philip Goldson Intl -> SPR San Pedro, ~20-min puddle-jumper (Tropic Air / Maya Island Air) or ~90-min water taxi via Caye Caulker.","English is Belize''s official language - the only English-official nation in Central America."],"safety":{"emergency":"911 (also 90); San Pedro Police 206-2022; San Pedro Coast Guard 222-5260","hyperbaric_chamber":"YES - on Ambergris/San Pedro: SSS Belize Hyperbaric Facility (est. 1989, 4-diver lock, US Navy tables, 24/7) + DAN-affiliated Belize Chamber Project (2015). National dive-safety asset.","hospital":"Lighthouse Medical Center (San Pedro, private) for urgent care; serious trauma -> Karl Heusner Memorial Hospital (KHMH), Belize City - the only trauma centre in Belize; then US evac. Island remoteness flagged.","book_enabled":true,"l3_disclosure":true,"consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for the country (level + reason + named-danger areas + complete ''If you decide to travel'' guidance), pulled live, plus traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"},"state_dept_carveout":"cayes/San Pedro open; only Southside Belize City (Haulover Creek Canal to Fabers Road) restricted","stay_in_zone":true,"air_access_verified":true,"malaria":"none on the cayes; Belize WHO-certified malaria-free 2023; small mainland Cayo District cluster (Apr 2025) - mainland only","water":"do not drink tap water on the cayes; use bottled/filtered","mosquito_borne":"dengue primary concern; also chikungunya, Zika (day-biting Aedes) - use repellent","founder_policy_note":"book_enabled rides on the BOOK WITH WARNING bin (Four-Bin v3): full verbatim live US State Dept advisory disclosed + acknowledged at booking; only Southside Belize City is the named danger"},"timing":{"inflection_curve_start":"2026-12-20","peak":"late-Dec through April (dry season); dive peak extends to June","fire_date":"2026-12-08","fire_date_secondary":"2026-11-01 (Mar-Apr dive/whale-shark surge, 4-6 mo lead)","shoulder":"September-November (wet/green season, lower rates)","green":"September-November","booking_lead":"4-6 months (dive/liveaboard/atoll + ultra private-island)","off_season_specials":"green-season weekly/monthly villa & condo discounts","event_peaks":["San Pedro Lobster Festival (early summer; 2026 advertised Jul 1-12)","Costa Maya Festival (August; 2026 dates unverified)"],"whale_shark_window":"Mar-Jun full-moon (2026 full moons Mar 14, Apr 13); Apr-May best"},"jewels":[{"name":"Hol Chan Marine Reserve (Zone A)","si_tag":"Dive Liveaboards / Reef Diving","status":"live","hook":"Signature 30-ft dive/snorkel; moray, turtles, 160+ fish species in a protected channel.","bookable_category":"guided dive/snorkel","tier":"comfort","source":"https://en.wikipedia.org/wiki/Hol_Chan_Marine_Reserve + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards / Reef Diving","blurb":"Signature 30-ft dive/snorkel; moray, turtles, 160+ fish species in a protected channel.","when":"late-Dec through April","commission":"David CLIA dive lane","accessed":"2026-07-06"},{"name":"Shark Ray Alley (Zone D)","si_tag":"Dive Liveaboards / Reef Diving","status":"live","hook":"Guided shallow encounter with docile nurse sharks and southern stingrays.","bookable_category":"guided snorkel/dive","tier":"comfort","source":"https://ambergrisdivers.com/trip/snorkeling-hol-chan-shark-ray-alley-marine-reserve/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards / Reef Diving","blurb":"Guided shallow encounter with docile nurse sharks and southern stingrays.","when":"late-Dec through April","commission":"David CLIA dive lane","accessed":"2026-07-06"},{"name":"Mexico Rocks & Tres Cocos","si_tag":"Dive Liveaboards / Reef Diving","status":"live","hook":"Shallow patch-reef gardens north of town; ideal for new divers and long snorkels.","bookable_category":"guided dive/snorkel","tier":"comfort","source":"https://www.backpackerswanderlust.com/diving-in-ambergris-caye-belize/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards / Reef Diving","blurb":"Shallow patch-reef gardens north of town; ideal for new divers and long snorkels.","when":"late-Dec through April","commission":"David CLIA dive lane","accessed":"2026-07-06"},{"name":"Great Blue Hole + Lighthouse Reef","si_tag":"Dive Liveaboards / Reef Diving","status":"live","hook":"Bucket-list 410-ft UNESCO sinkhole; full-day boat or scenic-flight-and-dive combo.","bookable_category":"dive expedition / air combo","tier":"premier","source":"https://ambergrisdivers.com/trip/great-blue-hole-dive-and-lighthouse-reef-day-tour/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards / Reef Diving","blurb":"Bucket-list 410-ft UNESCO sinkhole; full-day boat or scenic-flight-and-dive combo.","when":"late-Dec through April","commission":"David CLIA dive lane + air affiliate","accessed":"2026-07-06"},{"name":"Bacalar Chico National Park & Marine Reserve","si_tag":"Dive Liveaboards / Reef Diving","status":"live","hook":"Remote far-north reef, mangrove and Maya-history diving near the Mexico border.","bookable_category":"dive expedition / private charter","tier":"premier","source":"https://www.viaventure.com/destinations/belize/ambergris-caye/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards / Reef Diving","blurb":"Remote far-north reef, mangrove and Maya-history diving near the Mexico border.","when":"late-Dec through April","commission":"David CLIA dive lane","accessed":"2026-07-06"},{"name":"Grand Slam fly-fishing (bonefish + permit + tarpon)","si_tag":"GEA","status":"live","hook":"400+ sq mi of flats; El Pescador Orvis-endorsed base; all three species in a day.","bookable_category":"lodge / guided angling","tier":"luxury","source":"https://www.elpescador.com/articles/from-bonefish-to-tarpon-the-anglers-guide-to-el-pescadors-grand-slam/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"400+ sq mi of flats; El Pescador Orvis-endorsed base; all three species in a day.","when":"late-Dec through April","commission":"CLIA + Fora (lodge/villa)","accessed":"2026-07-06"},{"name":"Gladden Spit whale-shark encounter","si_tag":"GEA","status":"live","hook":"Mar-Jun full-moon aggregation; snorkel/dive with whale sharks (mainland-launched marquee day-add).","bookable_category":"guided dive/snorkel","tier":"premier","source":"https://belizescuba.com/diving-snorkeling/whale-sharks/ + Accessed 2026-07-06","si":"expedition","blurb":"Mar-Jun full-moon aggregation; snorkel/dive with whale sharks (mainland-launched marquee day-add).","commission":"David CLIA dive lane","accessed":"2026-07-06"},{"name":"Caye Caulker day trip","si_tag":"GEA","status":"live","hook":"Car-free ''go slow'' sister island 30 min by boat; the Split, cheaper eats.","bookable_category":"day tour / water taxi","tier":"essential","source":"https://www.viaventure.com/destinations/belize/ambergris-caye/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Car-free ''go slow'' sister island 30 min by boat; the Split, cheaper eats.","when":"late-Dec through April","commission":"tour affiliate (Viator) + water taxi","accessed":"2026-07-06"},{"name":"Secret Beach (west side)","si_tag":"Tropical Islands / Beaches","status":"live","hook":"Famous shallow-lagoon bar-and-beach scene; golf-cart destination, calm swim water.","bookable_category":"day trip / F&B","tier":"comfort","source":"https://agentsgather.com/vacation-rentals-ambergris-caye-belize/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Tropical Islands / Beaches","blurb":"Famous shallow-lagoon bar-and-beach scene; golf-cart destination, calm swim water.","when":"late-Dec through April","commission":"tour + F&B affiliate","accessed":"2026-07-06"},{"name":"San Pedro town + Belikin nightlife","si_tag":"Tropical Islands / Beaches","status":"live","hook":"Sand-street town core, dockside bars, live music, Lobster Festival hub.","bookable_category":"F&B / event","tier":"essential","source":"https://www.thephoenixbelize.com/explore-more/ultimate-guide-belize-lobster-season-san-pedro + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Tropical Islands / Beaches","blurb":"Sand-street town core, dockside bars, live music, Lobster Festival hub.","when":"late-Dec through April","commission":"F&B / event affiliate","accessed":"2026-07-06"},{"name":"Sunset sail / private charter","si_tag":"Romance & Honeymoons","status":"live","hook":"Champagne catamaran sail over the reef lagoon; the honeymoon signature.","bookable_category":"charter / activity","tier":"premier","source":"https://www.viaventure.com/destinations/belize/ambergris-caye/ + Accessed 2026-07-06","timing":"late-Dec through April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Champagne catamaran sail over the reef lagoon; the honeymoon signature.","when":"late-Dec through April","commission":"Fora / activity affiliate","accessed":"2026-07-06"}],"faq":[{"q":"What is the best diving and snorkeling on Ambergris Caye?","a":"Start at Hol Chan Marine Reserve and Shark Ray Alley. The signature ~30-ft channel dive delivers moray, turtles and 160+ fish species, while Shark Ray Alley — added as Zone D in 1999 — puts you in shallow water with docile 4–6 ft nurse sharks and southern stingrays. Both are guided, beginner-friendly profiles because they are shallow and protected.","source":"en.wikipedia.org, 2026-07-06","si_tag":"liveaboard"},{"q":"Do you need a car on Ambergris Caye?","a":"No — the island runs on golf carts, not cars, and beachfront San Pedro properties sit a 10-minute walk from the airstrip and steps from the water-taxi dock. English is the official language (Belize is the only English-official nation in Central America), so North American travelers move through town with zero language friction.","source":"agentsgather.com, 2026-07-06","si_tag":"tropical"},{"q":"Where should you stay for a honeymoon on Ambergris Caye?","a":"For seclusion, Cayo Espanto is a private island 3 miles off San Pedro with 7 all-inclusive villas and an 18-guest cap from ~US$1,695/villa/night; for adults-only boutique romance, Matachica offers thatched casitas. Both read romance-forward because the property caps guest count and builds the stay around couples.","source":"aprivateisland.com, 2026-07-06","si_tag":"romance"},{"q":"Can you fish the Grand Slam from Ambergris Caye?","a":"Yes — Ambergris fronts 400+ sq mi of flats, channels and lagoons where bonefish, permit and tarpon can all be landed in one day, with El Pescador the Orvis-endorsed base for 50+ years. Tarpon peaks July–September; bonefish and permit run year-round, so the slam is a realistic single-day target.","source":"elpescador.com, 2026-07-06","si_tag":"expedition"},{"q":"What''s the real risk to plan for on Ambergris Caye?","a":"Island remoteness for serious medical events, not crime. San Pedro''s Lighthouse Medical Center handles urgent care, but serious trauma routes to Karl Heusner Memorial Hospital in Belize City — the only trauma centre in Belize — then to the US, requiring air/water transfer off the island. Dengue is the primary mosquito-borne concern; there is no malaria on the cayes (Belize was WHO-certified malaria-free in 2023).","source":"belizetravelinsider.com, 2026-07-06","si_tag":"safety"},{"q":"Is diving the Great Blue Hole dangerous?","a":"It is an advanced dive, not a beginner novelty. The Blue Hole bottoms below recreational limits (~410 ft total); recreational dives target ~130 ft along the stalactite ledges, so treat it as advanced/technical-adjacent with sound gas planning. The offshore boat crossing is 2.5–3 hours each way, or ~20 minutes by scenic flight from San Pedro.","source":"ambergriscaye.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Ambergris Caye & San Pedro, Belize: Dive the Reef, Stay Well | TravelWell.World","meta_description":"Belize''s #1 island — dive Hol Chan and Shark Ray Alley, honeymoon at Cayo Espanto or Matachica, chase the Grand Slam on the flats. National hyperbaric chamber on-island. TravelWell.","slug":"ambergris-caye-belize","primary_keyword":"Ambergris Caye Belize","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06","search_language":"en","local_keywords":["Ambergris Caye Belize","San Pedro Belize diving","Hol Chan Marine Reserve snorkel","Ambergris Caye honeymoon resort","Cayo Espanto private island Belize","Belize barrier reef diving","Ambergris Caye villa rental","Shark Ray Alley tour","Belize Grand Slam fly fishing","Great Blue Hole day trip San Pedro"],"hreflang":["en"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"Dive Liveaboards / Reef Diving","status":"live"},{"si":"romance","status":"live"},{"si":"expedition","status":"live"}],"ultra":[{"name":"Cayo Espanto","why_ultra":"Private-island, 7 all-inclusive seafront villas incl. overwater Casa Ventanas, 18-guest cap, 24-hr dedicated houseman, chef-tailored meals, whole-island buyout.","earning":"Fora lane (AOR commissionable)","virtuoso_value_add":"resort credit / arrival amenity / upgrade on availability where consortia-eligible (confirm preferred status)","mor":"commissionable AOR (not merchant)","tier":"ultra"},{"name":"Victoria House Resort & Spa","why_ultra":"Five-star colonial-Caribbean flagship, spa, personalized service; ranks with the island''s top hotels.","earning":"Fora lane (AOR commissionable)","virtuoso_value_add":"consortia amenity where eligible","mor":"commissionable AOR","tier":"luxury"},{"name":"Matachica Resort & Spa","why_ultra":"Adults-only boutique, private thatched casitas, romance-forward.","earning":"Fora lane (AOR commissionable)","virtuoso_value_add":"consortia amenity where eligible","mor":"commissionable AOR","tier":"luxury"},{"name":"Las Terrazas","why_ultra":"Design-led north-shore residences, full kitchens, sea-view balconies.","earning":"Fora lane (AOR commissionable)","virtuoso_value_add":"consortia amenity where eligible","mor":"commissionable AOR","tier":"luxury"}],"source_verified":"2026-07-06","hero":{"query":"Ambergris Caye / San Pedro, Belize"},"geo":{"lat":17.9214,"lng":-87.9611}}'::jsonb, 4),
  ('blue-hole-belize', '10S', 'The Belize Atolls & Blue Hole', 'Belize', 'Atolls, walls and the Blue Hole', 'live', 'verified', 'oceanAerial', 'Belize', '{"liveaboard","expedition","tropical"}', '{"tropical"}', '{"comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Great Blue Hole is 318 m (1,043 ft) across and 124 m (407 ft) deep, near the center of Lighthouse Reef ~70 km (43 mi) off Belize City.","Belize has three coral atolls — Turneffe, Lighthouse Reef, Glover''s Reef — within the UNESCO-listed Belize Barrier Reef Reserve System.","Blue Hole stalactites hang at ~100-140 ft (30-42 m); the dive reaches ~40 m/130 ft with a narrow no-deco window — Advanced cert recommended.","Belize Aggressor III/IV depart Belize City Saturdays, up to 5 dives/day, 24-27 dives on a 7-night charter (39-42 on 10-night).","Whale sharks gather at Gladden Spit (southern Belize) around the full moon March-June."],"safety":{"emergency":"911","marine_vhf":"Channel 16","hyperbaric_chamber":"Belize Chamber Project Ltd, San Pedro (Ambergris Caye) — only DAN-Preferred chamber in Belize, 24/7; hours of boat+air transit from the offshore atolls","advisory_date":"2026-06-18","advisory_codes":"C (Crime) only","book_enabled":true,"consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for the country (level + reason + named-danger areas + complete ''If you decide to travel'' guidance), pulled live, plus traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"},"l3_disclosure":true,"state_dept_carveout":"only Southside Belize City restricted; offshore atolls open","stay_in_zone":true,"air_access_verified":true,"no_fly_after_diving":"12h single no-deco dive / 18h multi-day repetitive / 24h recommended buffer before BZE flight home","water":"open Caribbean ocean; no malaria offshore; high sun/sea exposure; DAN dive insurance with evac coverage effectively mandatory"},"timing":{"type":"dive-calendar","dive_calendar":true,"curve_start":"2026-02-15","peak":"March-June (Blue Hole best flat seas April-June)","whale_shark_window":["2026-03-14","2026-04-13","2026-05-12","2026-06-11"],"booking_lead_months":"4-6 (peak charters / full-boat buyouts longer)","shoulder_green_season":"September-November (wet/rougher, off-season fill)","fire_date":"2026-02-01","trigger_date":"2026-02-01","sharpen_note":"sharpen on live tracking — Aggressor charter availability + whale-shark sighting logs; flat-sea onset shifts yearly"},"jewels":[{"name":"The Great Blue Hole (Lighthouse Reef)","si_tag":"Dive Liveaboards/GEA","tier":"premier","source":"https://en.wikipedia.org/wiki/Great_Blue_Hole","timing":"March-June","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"A near-perfect flooded karst sinkhole near the center of Lighthouse Reef, roughly 70 km off Belize City","si":"Dive Liveaboards/GEA","blurb":"A near-perfect flooded karst sinkhole near the center of Lighthouse Reef, roughly 70 km off Belize City","when":"March-June","commission":"own-CLIA / TCI Land Agency lane (Aggressor)"},{"name":"Half Moon Caye Wall + Natural Monument","si_tag":"Dive Liveaboards/Tropical Islands","tier":"premier","source":"https://ambergriscaye.com/pages/town/divelighthouse.html","timing":"year-round","timing_type":"ALWAYS-ON","hook":"is rated by many divers as the single best dive site in Belize","si":"Dive Liveaboards/Tropical Islands","blurb":"is rated by many divers as the single best dive site in Belize","when":"year-round","commission":"own-CLIA liveaboard lane; park fee non-commissionable"},{"name":"The Painted Wall & Quebrada (Lighthouse Reef)","si_tag":"liveaboard","tier":"premier","source":"https://www.aggressor.com/kbyg_document/Belize","timing":"March-June","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"March-June","commission":"own-CLIA liveaboard lane"},{"name":"Turneffe Elbow (Turneffe Atoll)","si_tag":"Dive Liveaboards/GEA","tier":"comfort","source":"https://www.divessi.com/en/mydiveguide/divesite/98293","timing":"March-June","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards/GEA","when":"March-June","commission":"own-CLIA liveaboard lane or Fora via Turneffe resorts"},{"name":"Glover''s Reef (remote atoll)","si_tag":"Dive Liveaboards/GEA","tier":"premier","source":"https://www.belizeadventure.ca/atolls-of-belize/","timing":"March-June","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Dive Liveaboards/GEA","when":"March-June","commission":"own-CLIA liveaboard lane (scarcity — few boats reach it)"},{"name":"Gladden Spit whale sharks (seasonal, southern Belize)","si_tag":"GEA/Dive Liveaboards","tier":"comfort","source":"https://belizescuba.com/diving-snorkeling/whale-sharks/","si":"GEA/Dive Liveaboards","commission":"AFF/day-operator or Fora via Placencia; marine-reserve fee non-commissionable"},{"name":"Tobacco Caye","si_tag":"tropical","tier":"comfort","source":"https://www.belizeadventure.ca/atolls-of-belize/","timing":"March-June","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"March-June","commission":"Fora lane (small guesthouse packages)"},{"name":"Long Caye (Lighthouse Reef)","si_tag":"Tropical Islands/Dive Liveaboards","tier":"comfort","source":"https://www.belizehighcommission.com/areas-of-belize/lighthouse-reef-bz","timing":"March-June","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Tropical Islands/Dive Liveaboards","when":"March-June","commission":"Fora / own-CLIA depending on operator"}],"faq":[{"q":"How many dives do you get on a Belize Aggressor liveaboard trip?","a":"Up to five dives a day — 24–27 dives on a 7-night charter, 39–42 on a 10-night. The Aggressor III/IV depart the Fort George dock in Belize City every Saturday at 6 pm, dive Sunday morning to Friday noon, and reach all three atolls, so the liveaboard converts a long day-boat run into unlimited access to Lighthouse Reef, Turneffe and Glover''s.","source":"aggressor.com, 2026-07-06","si_tag":"liveaboard"},{"q":"How deep is the Great Blue Hole dive and do you need to be certified?","a":"The dive reaches ~40 m/130 ft — at or beyond the recreational limit — to see the stalactites that hang between roughly 100–140 ft. Bottom time is measured in minutes and nitrogen narcosis is a real factor, so reputable operators strongly recommend or require Advanced Open Water certification. It is a deliberately deep dive, not a beginner novelty.","source":"dive-the-world.com, 2026-07-06","si_tag":"expedition"},{"q":"What is there to do on the Belize atolls if you don''t dive?","a":"The atoll cayes carry barefoot reef-island character for surface-interval and non-diver days. Tobacco Caye is a few-acre reef caye with snorkel-off-the-dock access; Half Moon Caye is a natural monument with ~4,000 nesting red-footed boobies and an observation tower; Long Caye is the inhabited base camp for Blue Hole and Half Moon Caye dives.","source":"belizeadventure.ca, 2026-07-06","si_tag":"tropical"},{"q":"What''s the real risk to plan for on an atoll dive trip?","a":"Offshore remoteness from the chamber. The only DAN-Preferred recompression chamber in Belize is on San Pedro, Ambergris Caye — hours of boat-then-air transit from a hit at Lighthouse Reef (~70 km/43 mi offshore) or Glover''s. Liveaboards carry onboard O2 and run DAN protocols as first response, which is why depth and deco discipline are non-negotiable and DAN insurance with evacuation coverage is effectively mandatory.","source":"ambergriscaye.com, 2026-07-06","si_tag":"safety"},{"q":"How long do you have to wait to fly after diving the Blue Hole?","a":"Plan an 18–24 hour buffer. DAN guidance sets a minimum 12-hour surface interval after a single no-deco dive and a minimum 18 hours after multi-day repetitive diving, which every liveaboard trip is; 24 hours is the recommended general practice. A 7-night Aggressor charter ends diving Friday around noon for a Saturday departure precisely to give that buffer before the BZE flight home.","source":"dan.org, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Great Blue Hole & Belize Atolls Diving — Liveaboard, Lighthouse Reef, Turneffe & Glover''s | TravelWell.World","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06","search_language":"en","local_keywords":["Belize Blue Hole liveaboard","diving Lighthouse Reef Belize","Belize Aggressor","Great Blue Hole dive depth","Turneffe Atoll diving","Glover''s Reef liveaboard","Half Moon Caye Wall dive","Belize whale shark diving Gladden Spit","no fly after diving Belize"],"hreflang":["en"]},"booking":null,"si_checklist_25":null,"sis_present":["liveaboard","expedition","tropical"],"ultra":[{"name":"Private full-boat liveaboard charter (Belize Aggressor III/IV buyout)","tier":"ultra","mor":"own-CLIA / TCI Land Agency lane — convertible affiliate->commissioned-agent (the moat)","source":"https://www.aggressor.com/destination/belize"},{"name":"Turneffe Island Resort (luxury all-inclusive dive)","tier":"luxury-ultra","mor":"Fora lane (host-agency IATA) all-inclusive dive package","source":"https://visitturneffe.org/discover/where-to-stay-on-turneffe-atoll/"},{"name":"Gladden Private Island (adjacent, southern Belize)","tier":"ultra","mor":"Fora / own-CLIA depending on channel","source":"https://www.belizeadventure.ca/atolls-of-belize/"}],"source_verified":"2026-07-06","hero":{"query":"The Belize Atolls & Blue Hole, Belize"},"geo":{"lat":17.3158,"lng":-87.5346}}'::jsonb, 5),
  ('bocas-del-toro-panama', '10S', 'Bocas del Toro, Panama', 'Panama', 'Islands strung on a turquoise thread', 'live', 'verified', 'mountainValley', 'Panama', '{"tropical","diveglobal","romance","adventure"}', '{}', '{"essential","comfort","luxury"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","advisory_level":"L2","advisory_text":"Exercise Increased Caution (crime + potential civil unrest)","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":true,"remote_flag":true,"hazards":["riptides (Red Frog)","advanced reef surf breaks (Bluff/Paunch)","water-taxi/boat transfers","dengue/zika/chikungunya","non-potable tap water (bottled only)"],"medical":"Bocas Town private clinic; Changuinola ~3h; Panama City evac ~11h road / short flight. Medical-evac insurance advised.","unrest_history":"State of emergency May-Jun 2025 (protests); lifted 2025-06-29; US personnel prohibition lifted 2025-07-08. Monitor before campaigns.","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/panama","read":"2026-08-19","page_updated":"2025-12-10T13:26:25+00:00"}},"timing":{"peak_windows":["Feb-Mar (driest + best viz + surf peak)","Sep-Oct (driest secondary + low crowds)"],"surf_peak":"Dec-Mar (secondary Jun-Jul)","inflection":"late Nov -> Dec","off_season_fill":["Nov (wettest)","Apr-May","Aug"],"fire_date":["~2026-01-18 (for Feb-Mar peak)","~2026-08-20 (for Sep-Oct peak)"],"note":"Caribbean-Panama inverts the national dry season; driest = Feb-Mar and Sep-Oct."},"jewels":[{"name":"Zapatilla Cays","si_tag":"tropical","tier":"essential","source":"https://go.bocasdeltoro.travel/destinations/cayos-zapatillas/","hook":"two uninhabited, reef-sheltered cays inside Bastimentos National Marine Park; postcard white sand + snorkeling","si":"tropical","blurb":"two uninhabited, reef-sheltered cays inside Bastimentos National Marine Park; postcard white sand + snorkeling","commission":"day-tour referral + non-commissionable park fee"},{"name":"Starfish Beach (Playa Estrella)","si_tag":"tropical","tier":"essential","source":"https://sallysees.com/beaches-in-bocas-del-toro/","hook":"shallow, glass-clear water full of starfish on Isla Colón''s northwest tip; the archipelago''s most photographed spot","si":"tropical","blurb":"shallow, glass-clear water full of starfish on Isla Colón''s northwest tip; the archipelago''s most photographed spot","commission":"island-hop boat-tour referral"},{"name":"Red Frog Beach","si_tag":"tropical","tier":"comfort","source":"https://www.redfrogbeach.com/about","si":"tropical","commission":"Red Frog Beach resort booking + boat transfer"},{"name":"Wizard Beach","si_tag":"tropical","tier":"essential","source":"https://mokumsurfclub.com/ultimate-bocas-del-toro-guide/","si":"tropical","commission":"guided walk / surf-school referral"},{"name":"Cayo Coral (Coral Cay)","si_tag":"Dive/Snorkel","tier":"essential","source":"https://www.snorkeling-report.com/spot/snorkeling-cayo-coral-bocas-del-toro/","hook":"easy patch reef, 10–12 ft, mooring buoys, floating restaurants alongside. Ideal first-timer snorkel","si":"Dive/Snorkel","blurb":"easy patch reef, 10–12 ft, mooring buoys, floating restaurants alongside. Ideal first-timer snorkel","commission":"dive/snorkel operator referral"},{"name":"Bastimentos National Marine Park reefs","si_tag":"Dive/Snorkel","tier":"comfort","source":"https://www.tourismpanama.com/outdoors-and-nature/nature-parks/national-parks/bastimentos-island/","si":"Dive/Snorkel","commission":"PADI operator package + park fee"},{"name":"Dolphin Bay","si_tag":"Dive/Snorkel","tier":"essential","source":"https://bocastours.com/en/packages/zapatilla-cay-tour","hook":"resident dolphin pods; combines with Zapatilla day tours","si":"Dive/Snorkel","blurb":"resident dolphin pods; combines with Zapatilla day tours","commission":"boat-tour referral (ethical operators)"},{"name":"Bioluminescence night tour","si_tag":"romance","tier":"essential","source":"https://azoravoyages.com/customize-my-trip/panama-all-tours/bocas-del-toro-activities-tours/","hook":"2-hr boat rides across dark bays where plankton light up on movement. Pure honeymoon set-piece","si":"romance","blurb":"2-hr boat rides across dark bays where plankton light up on movement. Pure honeymoon set-piece","commission":"guided night-tour referral"},{"name":"Overwater villa nights (Nayara)","si_tag":"romance","tier":"luxury","source":"https://nayarabocasdeltoro.com/stay/","hook":"adults-only, plunge pools, glass-floor windows over the reef","si":"romance","blurb":"adults-only, plunge pools, glass-floor windows over the reef","commission":"luxury AOR / bedbank / affiliate"},{"name":"Oreba / Ngäbe cacao-farm tour","si_tag":"expedition","tier":"essential","source":"https://www.tourismpanama.com/places-to-visit/bocas-del-toro/things-to-do/culture-and-arts/indigenous-communities/","hook":"indigenous-guided walk through a working cacao farm + artisanal chocolate. Cultural moat + weather-tolerant","si":"expedition","blurb":"indigenous-guided walk through a working cacao farm + artisanal chocolate. Cultural moat + weather-tolerant","commission":"community-tour referral"},{"name":"Bahía Honda Timorogo aquatic-trail + bat cave","si_tag":"expedition","tier":"essential","source":"https://www.natureretreats.org/listing/ngobe-timorogo-community-ecotourism-project/","hook":"community ecotourism boat trail into a bat cave","si":"expedition","blurb":"community ecotourism boat trail into a bat cave","commission":"community-tour referral"},{"name":"Surf the Bluff / Paunch / Wizard","si_tag":"expedition","tier":"essential","source":"https://mokumsurfclub.com/ultimate-bocas-del-toro-guide/","hook":"Sharp split by ability: Bluff and Paunch are advanced reef breaks; Wizard is beginner-friendly when small and used by surf schools","si":"expedition","blurb":"Sharp split by ability: Bluff and Paunch are advanced reef breaks; Wizard is beginner-friendly when small and used by surf schools","commission":"surf-school / lesson referral"},{"name":"Bocas Town Caribbean nightlife","si_tag":"expedition","tier":"essential","source":"https://www.takeyourbackpack.com/backpacking-in-panama/visit-bocas-del-toro/","hook":"the stilted harbor town''s bars, over-water clubs, and reggae/soca scene","si":"expedition","blurb":"the stilted harbor town''s bars, over-water clubs, and reggae/soca scene","commission":"F&B / experience add-on (drives room-nights)"}],"faq":null,"seo":{"meta_title":"Bocas del Toro, Panama Travel Guide 2026 — Islands, Reefs, Overwater Villas | TravelWell","search_language":"es-PA","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","local_keywords":["Bocas del Toro qué hacer","Cayos Zapatillas","Isla Bastimentos","Bocas del Toro cuándo ir","playa Estrella Bocas","surf en Bocas del Toro","tour bioluminiscencia Bocas","villas sobre el agua Panamá"],"hreflang":["en","es-PA"]},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Nayara Bocas del Toro","island":"Frangipani","model":"luxury-resort / Virtuoso-style preferred","tier":"luxury","mor":false,"note":"CNT #1 Central America; adults-only overwater"},{"name":"Sweet Bocas","model":"whole-estate MoR buyout","tier":"$$$$$","mor":true,"note":"AD-featured 9-BR teak overwater private-island villa; ~26 adults; $10,500/night base"},{"name":"Red Frog Beach Island Resort","island":"Bastimentos","model":"resort + villa commission","tier":"$$$","mor":"villa inventory via Red Frog Property"},{"name":"Isla Palenque","model":"luxury private-island (Pacific Gulf of Chiriquí — NOT Bocas)","tier":"luxury","mor":false,"note":"two-coast Panama add-on, not a Bocas jewel"}],"source_verified":null,"hero":{"query":"Bocas del Toro, Panama, Panama"},"geo":{"lat":9.3402,"lng":-82.2417}}'::jsonb, 6),
  ('cabo-pulmo-mexico', '10S', 'Cabo Pulmo', 'Mexico', 'The Sea of Cortez, recovered', 'live', 'verified', 'mountainValley', 'Baja California Sur (Los Cabos & La Paz)', '{"expedition","diveglobal"}', '{}', '{"essential","premier"}', null, null, '{"key_facts":["Federally protected National Marine Park since June 5, 1995; ~71 km2 fully protected (Source: en.wikipedia.org/wiki/Cabo_Pulmo_National_Park, 2026-07-04)","463% total fish-biomass increase, ~11x top-predator jump by 2009 — most successful no-take recovery measured (Source: ocean.si.edu, 2026-07-04)","Only living hard-coral reef in the Sea of Cortez; UNESCO WHS 2005, Ramsar 2008 (Source: en.wikipedia.org, 2026-07-04)","CONANP no-take rules: guide-led 6:1, no touching, gloves banned, licensed pangas only (Source: mexicotraveladventure.com, 2026-07-04)","Off-grid village; ~2-3 h drive north of SJD / Los Cabos; eco-cabañas only, no luxury hotels (Source: sallysees.com, 2026-07-04)"],"safety":{"emergency":"911","nearest_trauma":"Cabo San Lucas / San Jose del Cabo (Los Cabos), ~2-3 h by road; La Paz alternative","advisory_level":"L2","advisory_note":"Baja California Sur US Level 2 (Exercise Increased Caution), May 29, 2026 — freely bookable, disclose L2, no hold","malaria":"none","dengue":"present in Baja California Sur; use repellent","water":"bottled/purified","hurricane":"May 15-Nov 30, peak Aug-Oct","remote_medevac":"off-grid; no chamber/hospital in village; multi-hour ground evac to Los Cabos","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Jul-Nov (best visibility, bull-shark aggregation)","shoulder":"Apr-Jun, late fall","green":"Dec-Feb (coolest water, wind days)","booking_window_lead_time":"2-4 months (capped dive slots + tiny bed inventory)","out_of_season_fill":"winter dive-and-stay packages; East Cape / Los Cabos day-trip combos","holiday_event_peaks":["US/Canada summer holidays","Los Cabos Dec-Apr high-season spillover"],"campaign_start_trigger":"late spring for summer-fall dive peak; Los Cabos winter high season for day-trip capture"},"jewels":[{"si_tag":"expedition","status":"live","tier":"essential","commission":"operator agreement","name":"Pulmo reef recovery dive","si":"expedition"},{"si_tag":"expedition","status":"live","tier":"premier","commission":"operator agreement","name":"Bull-shark aggregation dive","si":"expedition"},{"si_tag":"expedition","status":"live","tier":"essential","commission":"operator + DMC","name":"Protected-reef snorkel","si":"expedition"},{"si_tag":"expedition","status":"live","tier":"premier","commission":"operator agreement","name":"Sea-lion / offshore pinnacle dives","si":"expedition"},{"si_tag":"diveglobal","status":"future","tier":"premier","commission":"operator; stay direct","name":"Multi-day Cabo Pulmo dive-and-stay","si":"diveglobal"}],"faq":[{"q":"Is Cabo Pulmo worth diving, and what will I see?","a":"Yes — it is arguably the Sea of Cortez''s best dive, because protection worked: total fish biomass rebounded 463% by 2009 on the Gulf''s only living hard-coral reef. Expect schooling jacks, groupers and rays, and in warm summer–fall water a bull-shark aggregation.","source":"ocean.si.edu / divearoo.com, 2026-07-04","si_tag":"expedition"},{"q":"Do I need to be certified, and can non-divers go?","a":"You dive within your card with a mandatory park guide (max 6 divers each), and non-divers can snorkel the same no-take reef. The rules are strict — no gloves, no touching, licensed pangas only — and enforced; break them and you can be pulled from the water.","source":"mexicotraveladventure.com, 2026-07-04","si_tag":"diveglobal"},{"q":"Can couples make a romantic escape of Cabo Pulmo?","a":"Only if \"romantic\" means off-grid and simple — there is no resort or spa layer. Lodging is solar eco-cabañas and a tiny villa cluster (~5 villas), which suits low-key couples; anyone wanting branded luxury bases in Los Cabos or the East Cape and day-trips in.","source":"sallysees.com / cabopulmo.com, 2026-07-04","si_tag":"romance"},{"q":"Is diving here dangerous — what''s the real risk?","a":"The gatekeeper is medevac distance, not the diving itself. Cabo Pulmo is off-grid with no chamber or hospital in the village; the nearest recompression chamber and trauma care are ~2–3 hours away in Los Cabos, so dive conservatively, carry DAN cover, and observe 18–24 h no-fly before an SJD departure.","source":"sssnetwork.com / dan.org, 2026-07-04","si_tag":"safety"}],"seo":{"meta_title":"Cabo Pulmo Diving — Sea of Cortez No-Take Reef | TravelWell.World","meta_description":"Dive Cabo Pulmo, the most-recovered no-take marine reserve in the Sea of Cortez. Guided park dives, no-touch rules, eco-cabaña stays, Los Cabos gateway logistics.","primary_keywords":["Cabo Pulmo diving","Cabo Pulmo National Park","Cabo Pulmo snorkeling","Sea of Cortez reef"],"long_tail":["best time to dive Cabo Pulmo","Cabo Pulmo bull shark season","how to get to Cabo Pulmo from Los Cabos","Cabo Pulmo eco cabañas"],"search_language":"es-MX","local_keywords":["buceo Cabo Pulmo","Parque Nacional Cabo Pulmo","arrecife de coral Mar de Cortes","snorkel Cabo Pulmo","reserva marina sin pesca","cabanas ecologicas Cabo Pulmo"],"hreflang":["en","es-MX"],"jsonld_type":"TouristAttraction","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":["expedition","diveglobal"],"ultra":[{"what":"Four Seasons Los Cabos at Costa Palmas / Amanvari (East Cape, Los Cabos) as luxury base for a Cabo Pulmo dive charter","why_ultra":"largest swimmable beach + only private marina in Los Cabos; Amanvari is first Aman in Mexico (spring 2026)","earning":"on application / via host-Virtuoso","virtuoso_value_add":"resort credit, upgrade, breakfast; private guide for Pulmo run","mor":"resale via host-Virtuoso only; Cabo Pulmo itself is NOT an ultra stay — nearest ultra is Los Cabos"}],"source_verified":"2026-07-04","hero":{"query":"Cabo Pulmo, Mexico"},"geo":{"lat":23.4433,"lng":-109.4283}}'::jsonb, 7),
