  ('cancun-mexico', '10S', 'Cancún', 'Mexico', 'The gateway where a barrier reef meets a runway', 'live', 'verified', 'tropicalBeach', 'Quintana Roo (Cancún & Riviera Maya)', '{"tropical","adventure","diveglobal","ocean"}', '{"tropical"}', '{"essential","comfort"}', null, 'anchor', '{"key_facts":["Sits on the Mesoamerican Barrier Reef, world''s 2nd-longest coral reef system","MUSA underwater museum: 470+ statues, 3.5-8 m, divable and snorkelable","World''s largest whale-shark aggregation offshore mid-May to mid-Sept (snorkel-only)","Best overall window Jan-Mar (clearest water, lowest sargassum)","Gateway hub for cenotes, Chichen Itza/Tulum, Isla Mujeres and Contoy"],"safety":{"emergency":"911","hospital":"Galenia + Hospiten Cancún (verify trauma status); hyperbaric via SSS Cancún / Cozumel","advisory_level":"L2","malaria":"none in QR tourist zones (verify); dengue precautions","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dec-Apr (dry, lowest sargassum, highest price/crowds)","shoulder":"late Apr-Jun & Nov (~30-40% off, good weather)","green":"Jul-Oct (hurricane/rain, 40-60% below peak Sep-Oct)","booking_lead":"~3-4 months for Dec-Apr peak & spring break; 2-3 months off-peak","off_season_specials":"~30-40% off May-Jun & Nov shoulder; 40-60% off Sep-Oct green trough","event_peaks":["Spring Break (Mar)","whale-shark run mid-May-mid-Sept peak Jun-Aug","winter holidays late Dec"],"campaign_start":"market Dec-Apr peak by ~September; push whale-shark green-season from ~March"},"jewels":[{"name":"MUSA Underwater Museum","si_tag":"diveglobal","status":"future","hook":"470+ submerged sculptures, divable by OW divers and snorkelers","bookable_category":"dive/snorkel/glass-bottom tour","tier":"comfort","source":"https://www.bluewaterdivetravel.com/scuba-musa-isla-mujeres-cancun","timing":"year-round","timing_type":"ALWAYS-ON","si":"diveglobal","blurb":"470+ submerged sculptures, divable by OW divers and snorkelers","when":"year-round","commission":"local dive-op/DMC → Viator/GYG affiliate"},{"name":"Whale-shark aggregation run","si_tag":"ocean","status":"future","hook":"snorkel the world''s largest whale-shark gathering, Jun-Aug peak","bookable_category":"boat snorkel excursion","tier":"comfort","source":"https://www.islandlifemexico.com/cancun-snorkeling-diving-guide/","si":"ocean","blurb":"snorkel the world''s largest whale-shark gathering, Jun-Aug peak","commission":"DMC/operator → OTA affiliate"},{"name":"Route of the Cenotes","si_tag":"globaladv","status":"live","hook":"jungle-road cenote circuit for swim/dive/zipline","bookable_category":"day tour + entry","tier":"essential","source":"https://www.islandlifemexico.com/cancun-snorkeling-diving-guide/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"jungle-road cenote circuit for swim/dive/zipline","when":"Dec-Apr","commission":"DMC → OTA (entry = pass-through)"},{"name":"Turtle-nesting programs (May-Sept)","si_tag":"globaladv","status":"live","hook":"green/hawksbill/loggerhead nesting + resort release programs","bookable_category":"eco/resort activity","tier":"essential","source":"https://www.islandlifemexico.com/cancun-snorkeling-diving-guide/","si":"adventure","blurb":"green/hawksbill/loggerhead nesting + resort release programs","commission":"resort/DMC (often pass-through)"},{"name":"South Hotel Zone / Playa Mujeres (sargassum-protected)","si_tag":"tropical","status":"live","hook":"cleaner beach stretches in a heavy sargassum year","bookable_category":"hotel + transfer","tier":"comfort","source":"https://www.howisthesargassum.com/blog/sargassum-june-2026-update","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","blurb":"cleaner beach stretches in a heavy sargassum year","when":"Dec-Apr","commission":"all-inclusive portal → Amstar transfer → OTA"}],"faq":[{"q":"What health risks should I actually plan for in Cancún?","a":"Water, mosquitoes, hurricanes and sargassum — not violent crime. Drink bottled/purified water; use repellent for dengue (no malaria in Quintana Roo tourist zones); hurricane season runs June–November with September riskiest; and sargassum peaks around July in 2026.","source":"travel.state.gov","si_tag":"safety"},{"q":"Will sargassum ruin the beaches in 2026?","a":"It''s a real risk in 2026 — plan location, don''t cancel. 2026 is tracking as one of the worst sargassum years on record, often peaking around July in the Riviera Maya; north Cancún and Playa Mujeres are among the more protected stretches, and Jan–March runs lowest on sargassum.","source":"howisthesargassum.com","si_tag":"tropical"},{"q":"When and how can I swim with whale sharks?","a":"Mid-May to mid-September, peaking June–August, on a snorkel-only boat excursion off Isla Mujeres/Holbox — the world''s largest whale-shark aggregation. It''s a green-season spike inside the low-price window, so rooms are cheaper then; life-vest, no-touch, follow-the-guide.","source":"islandlifemexico.com","si_tag":"ocean"},{"q":"Can beginners dive MUSA and the reef?","a":"Yes — MUSA is one of the most accessible dives anywhere. The 470+ statues sit 3.5–8 m down, shallow enough for Open Water divers, snorkelers and glass-bottom boats; no-fly-after-diving is 18–24 hours and these are shallow (≤9 m) day dives.","source":"bluewaterdivetravel.com","si_tag":"diveglobal"},{"q":"Is Cancún good for an all-inclusive honeymoon, and where''s the top end?","a":"Yes — it''s a honeymoon engine. The Hotel Zone is dense all-inclusive inventory; the one true ultra address in Cancún proper is NIZUC (Punta Nizuc, ~15 min from the airport), with the deepest luxury bench just down-corridor in Mayakoba/Maroma (Rosewood, Banyan Tree, Maroma/Belmond).","source":"virtuoso.com","si_tag":"tropical"}],"seo":{"meta_title":"Cancún, Mexico: Reef, MUSA & Whale-Shark Gateway","meta_description":"Cancún sits on the world''s second-longest reef — dive MUSA, snorkel the whale-shark run, base for cenotes and Maya ruins. Best time, safety, and how to book.","slug":"cancun-mexico","primary_keyword":"Cancún diving and snorkeling","long_tail":["Cancún MUSA underwater museum","Cancún whale shark tour season","best time to visit Cancún","Cancún all-inclusive honeymoon","Cancún cenote day trip"],"search_language":"EN primary + ES-MX; page answers real ES queries restated (not machine-translated)","local_keywords":["mejor época para viajar a Cancún","buceo MUSA Cancún","tour tiburón ballena Cancún","qué hacer en Cancún cenotes","Cancún todo incluido luna de miel","temporada de sargazo Cancún","villas de lujo Riviera Maya"],"hreflang":["en","es-MX","x-default:en"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":{"bin":"freely_bookable","level":"L2","codes":[],"consent_flow":false,"note":"Quintana Roo/Mexico US L2 (Exercise Increased Caution) - freely bookable; MXN currency, USD widely accepted"},"si_checklist_25":{"run_date":"2026-07-31","hits":9,"misses":13,"disregarded":3,"note":"Canonical 25-SI list; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"tropical","name":"tropical","status":"live"},{"si":"globaladv","name":"adventure","status":"live"},{"si":"diveglobal","name":"diveglobal","status":"future"},{"si":"ocean","name":"ocean","status":"future"}],"ultra":[{"name":"NIZUC Resort & Spa","why_ultra":"only true in-Cancún ultra enclave (Punta Nizuc), 274 suites/villas facing the reef","earning":"agent/consortium on application via host + Virtuoso","virtuoso_value_add":"Virtuoso member — free upgrades + amenities","mor":"safe (commissionable-rack / Virtuoso)"},{"name":"Rosewood Mayakoba","why_ultra":"boutique ~130 lagoon/beach suites, private pools + butler, on mangrove canals","earning":"agent/consortium on application via host + Virtuoso","virtuoso_value_add":"Virtuoso member","mor":"safe (commissionable-rack)"},{"name":"Banyan Tree Mayakoba","why_ultra":"all-villa private-pool privacy inside Mayakoba","earning":"agent/consortium on application via host + Virtuoso","virtuoso_value_add":"Virtuoso member","mor":"safe (commissionable-rack)"},{"name":"Fairmont Mayakoba","why_ultra":"full-amenity luxury tier of the Mayakoba four","earning":"agent/consortium on application via host","virtuoso_value_add":"verify (reported NOT Virtuoso; check Accor ALL/other)","mor":"safe (commissionable-rack)"},{"name":"Chablé Maroma","why_ultra":"wellness-forward design ultra, private beach, Jorge Vallejo dining","earning":"agent/consortium on application via host + Virtuoso","virtuoso_value_add":"verify present","mor":"safe (commissionable-rack)"},{"name":"Maroma, A Belmond Hotel","why_ultra":"legendary private-beach ultra, Belmond/LVMH tier","earning":"agent/consortium on application via host + Virtuoso","virtuoso_value_add":"Belmond typically Virtuoso — verify","mor":"safe (commissionable-rack)"},{"name":"La Casa de la Playa (by Xcaret)","why_ultra":"Xcaret''s top-tier ultra all-inclusive, adults/couples + eco-park access","earning":"agent/consortium via Xcaret trade / host on application","virtuoso_value_add":"verify","mor":"safe (commissionable-rack)"}],"source_verified":"2026-07-04","hero":{"query":"Cancún, Mexico"},"geo":{"lat":21.1619,"lng":-86.8515}}'::jsonb, 9),
  ('caye-caulker-belize', '10S', 'Caye Caulker', 'Belize', 'Caye Caulker Belize', 'live', 'verified', 'tropicalBeach', 'Belize', '{"tropical","liveaboard","expedition","ocean","culinary"}', '{"tropical"}', '{"essential","comfort"}', null, null, '{"key_facts":["Car-free ~5-mi caye; golf carts + bikes only; national motto ''Go Slow''; reached by water taxi (~45 min from Belize City) or Tropic Air / Maya Island Air airstrip","The Split = channel hand-widened after Hurricane Hattie (1961), now ~100 ft deep; island''s social heart + Lazy Lizard bar","Snorkel/dive base for the Belize Barrier Reef (UNESCO); Hol Chan Marine Reserve US$15 park fee (Belize''s oldest marine park)","Value counterpoint to Ambergris - budget-to-comfort island; hotel ceiling is boutique (Iguana Reef Inn / Weezie''s), no branded ultra on-island","Ragga 3-day/2-night sail Caulker->Placencia via Blue Hole/reef (~US$400, chef, Tue/Fri); manatees at Swallow Caye Wildlife Sanctuary (10 BZD fee)"],"safety":{"emergency":"911 (verify locally)","hyperbaric_chamber":"NOT on Caye Caulker - nearest is San Pedro/Ambergris Caye (Belize''s only chamber, next to Ambergris Hope Clinic, 226-2660); Caulker dive-accident cases boated to San Pedro - factor transfer time","hospital":"small local clinic on-caye; serious trauma routes to Belize City hospitals by water taxi/air or air-evac; route around Southside Belize City","book_enabled":true,"l3_disclosure":true,"consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for the country (level + reason + named-danger areas + complete ''If you decide to travel'' guidance), pulled live, plus traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"},"state_dept_carveout":"only Southside Belize City restricted; cayes open","stay_in_zone":true,"air_access_verified":"BZE -> Caye Caulker (CUK) by Tropic Air / Maya Island Air puddle-jumper, or high-speed water taxi ~45 min; never touches Southside Belize City","founder_policy_note":"book_enabled rides on the BOOK WITH WARNING bin (Four-Bin v3): full verbatim live US State Dept advisory disclosed + acknowledged at booking; only Southside Belize City is the named danger","the_split":"tidal current + boat traffic in the channel; not lifeguarded/boat-free; swim to sides, watch for boats, don''t swim impaired","malaria":"WHO-certified malaria-free (2023); a few mainland Cayo cases reappeared 2025; effectively none on the caye","dengue":"dengue/chikungunya/Zika active (daytime Aedes; Belize City cases up 2025) - DEET/picaridin, cover up","water":"tap water NOT potable - bottled/filtered only; mind ice/raw produce/unpasteurized dairy"},"timing":{"peak":"late-Dec-Apr (dry high season; Jan-Mar driest; Christmas-New Year + Easter sub-peaks)","dive_subpeak":"Mar-Jun (best viz, Blue Hole conditions)","shoulder_green":"Sep-Nov (green/rainy; Sep-Oct highest hurricane risk = value trough; late-Nov flips to dry comfort at low rates)","booking_window_lead_time":"value/short-lead market (weeks to a few months); 2-4 months for Dec-Apr peak + Christmas/Easter; book Blue Hole / 3-day Ragga sail ahead","out_of_season_fill_the_beds":"dive/sail value packages, Lobsterfest tail, manatee + Goff''s Caye day trips, ''slow island at half price'', Nov dry-comfort-at-low-rates","holiday_event_peaks":"Christmas-New Year, Easter, Lobsterfest (July), Independence season (Sep, overlaps hurricane risk)","fire_date":"peak: early-to-mid November (curve-start late-Nov minus 1-2 wks); dive/expedition: mid-February; green-value Nov push: late September; keep rolling last-minute layer year-round","flag":"value/short-lead market moves the curve faster than resort markets; Sep-Oct hurricane risk overlaps green window - sharpen on live booking-pace tracking","sources":["https://www.ashtoncourtbelize.com/blog/when-is-the-best-time-to-visit-caye-caulker.html","https://www.zubludiving.com/destination/belize/belize-district/ambergris-caye-san-pedro-caye-caulker","https://www.raggasailadventures.com/","https://www.thoroughlytravel.com/hotels-caye-caulker/"]},"jewels":[{"si_tag":"tropical","name":"The Split + Lazy Lizard sunset swim","why":"hand-cut channel, crystal water, the island''s social heart at golden hour","timing":"year-round, best sunset","tier":"essential","source":"https://en.wikipedia.org/wiki/Caye_Caulker","si":"tropical","when":"year-round, best sunset","commission":"F&B/OTA-adjacent scene-setter, not a margin line"},{"si_tag":"tropical","name":"Bike / golf-cart the car-free island","why":"the whole Go Slow experience in an afternoon","timing":"year-round","tier":"essential","source":"https://www.nomadicmatt.com/travel-guides/belize-travel-tips/caye-caulker/","si":"tropical","when":"year-round","commission":"local rental affiliate / DMC add-on"},{"si_tag":"liveaboard","name":"Hol Chan Marine Reserve + Shark Ray Alley","why":"Belize''s oldest marine park; sharks/rays/turtles; US$15 fee","timing":"year-round, best viz Mar-Jun","tier":"essential","source":"https://www.backpackerswanderlust.com/caye-caulker-snorkeling-tours/","si":"liveaboard","when":"year-round, best viz Mar-Jun","commission":"local dive/snorkel operator + Viator/GYG affiliate; CLIA dive-lane convert to commissioned where offered"},{"si_tag":"liveaboard","name":"Coral Gardens + seahorse stop","why":"shallow coral + seahorses on mangrove/grass roots - the caye''s signature soft moment","timing":"year-round","tier":"essential","source":"https://www.getyourguide.com/caye-caulker-l2496/caye-caulker-7-stop-snorkeling-in-the-belize-barrier-reef-t364340/","si":"liveaboard","when":"year-round","commission":"local operator + GYG affiliate"},{"si_tag":"expedition","name":"Manatee + Goff''s Caye day tour (Swallow Caye Sanctuary)","why":"West Indian manatees in a protected sanctuary + sandbar-caye lunch","timing":"late-Dec-Apr","tier":"comfort","source":"https://www.thoroughlytravel.com/swimming-with-manatees-belize/","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"late-Dec-Apr","commission":"local operator + DMC + Viator affiliate (10 BZD sanctuary fee non-commissionable)"},{"si_tag":"Global Expedition Adventures / Ocean Adventures","name":"Ragga 3-day sail to Blue Hole / Placencia","why":"sail the reef, camp on cayes, chef-cooked lobster on deck - the caye''s bucket-list expedition","timing":"year-round, Tue/Fri departures","tier":"comfort","source":"https://www.raggasailadventures.com/","si":"Global Expedition Adventures / Ocean Adventures","when":"year-round, Tue/Fri departures","commission":"Ragga tour commission on application + dive-lane crossover"},{"si_tag":"ocean","name":"Sunset sailing cruise","why":"casual catamaran sundowner off the reef","timing":"year-round evenings","tier":"essential","source":"https://www.raggasailadventures.com/","si":"ocean","when":"year-round evenings","commission":"local operator + affiliate"},{"si_tag":"culinary","name":"Fry-jack breakfast + lobster season / Lobsterfest","why":"fried-dough island breakfast; July Lobsterfest; lobster in-season ~mid-Jun-mid-Feb","timing":"Lobsterfest July; lobster Jun-Feb","tier":"essential","source":"https://www.nomadicmatt.com/travel-guides/belize-travel-tips/caye-caulker/","si":"culinary","when":"Lobsterfest July; lobster Jun-Feb","commission":"F&B/event affiliate-adjacent"},{"si_tag":"ocean","name":"Kitesurfing off the reef flats","why":"steady trade-wind flats for kite","timing":"~Nov-Jun windier window","tier":"comfort","source":"https://www.backpackerswanderlust.com/caye-caulker-snorkeling-tours/","si":"ocean","when":"~Nov-Jun windier window","commission":"local kite school + affiliate"}],"faq":[{"q":"How do you get around Caye Caulker — do you need a car?","a":"No cars at all. The ~5-mile island runs on bikes (from ~15 BZD/day) and golf carts (~125–150 BZD/day) on sand streets, reached by high-speed water taxi (~45 min from Belize City) or small plane on the Tropic Air / Maya Island Air airstrip. The whole \"Go Slow\" experience is walkable and bikeable in an afternoon.","source":"nomadicmatt.com, 2026-07-06","si_tag":"tropical"},{"q":"Is Caye Caulker good for snorkeling and diving?","a":"Yes — it is a value snorkel/dive base on the same Belize Barrier Reef as Ambergris. The Hol Chan Marine Reserve trip (US$15 park fee) puts you with sharks, rays and turtles in Belize''s oldest marine park; local operators run half-days ~US$50 and full-days ~US$90, with best visibility March–June.","source":"backpackerswanderlust.com, 2026-07-06","si_tag":"liveaboard"},{"q":"Can you sail to the Blue Hole from Caye Caulker?","a":"Yes — the Ragga 3-day/2-night sail (~US$400, Tuesday/Friday departures) runs Caulker to Placencia via the Blue Hole and reef, camping on tiny cayes with chef-cooked lobster on deck. Day options add manatees at Swallow Caye Wildlife Sanctuary (10 BZD sanctuary fee).","source":"raggasailadventures.com, 2026-07-06","si_tag":"expedition"},{"q":"What''s the food and lobster scene on Caye Caulker?","a":"Fry-jack breakfasts and beach BBQ anchor the everyday scene, and Lobsterfest lands in July as the island''s biggest food event. Lobster season itself runs roughly mid-June to mid-February, so a summer visit catches both the festival and fresh lobster.","source":"nomadicmatt.com, 2026-07-06","si_tag":"culinary"},{"q":"What''s the real risk to plan for on Caye Caulker?","a":"Two things: there is no recompression chamber on Caulker (nearest is San Pedro/Ambergris, so dive-accident cases are boated across — build in transfer time and carry DAN), and The Split is not a lifeguarded beach. The channel has tidal current and boat traffic, so swim to the sides, watch for boats, and don''t swim impaired at the Lazy Lizard. Hurricane risk peaks Sep–Oct.","source":"ambergriscaye.com, 2026-07-06","si_tag":"safety"},{"q":"Is diving the Blue Hole from here dangerous?","a":"It is a deep dive (>100 ft) for experienced/advanced divers only — verify certification and operator briefing. Allow 18–24 hours before flying, because many guests leave BZE by puddle-jumper, and remember the nearest chamber is on Ambergris, so plan conservative profiles and factor the boat transfer time.","source":"zubludiving.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Caye Caulker Belize: The ''Go Slow'' Island Guide","meta_description":"Snorkel Hol Chan with sharks and rays, swim The Split at sunset, sail the Blue Hole — Caye Caulker is Belize''s car-free ''Go Slow'' caye and the value counterpoint to Ambergris. When, how, and how to stay safe.","slug":"caye-caulker-belize","primary_keyword":"Caye Caulker Belize","long_tail":["Caye Caulker Go Slow island","The Split Caye Caulker swimming","Caye Caulker snorkeling Hol Chan","Caye Caulker vs Ambergris Caye budget","how to get to Caye Caulker from Belize City","Raggamuffin Blue Hole 3-day sail","Caye Caulker where to stay budget"],"search_language":"en","local_keywords":["Cayo Caulker Belice","bucear Cayo Caulker","snorkel Hol Chan Belice","cómo llegar a Cayo Caulker","hoteles económicos Cayo Caulker"],"hreflang":["en"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"liveaboard","status":"live"},{"si":"expedition","status":"live"},{"si":"ocean","status":"future"},{"si":"culinary","status":"future"}],"ultra":[{"name":"Cayo Espanto","location":"private island 3 mi off San Pedro / Ambergris Caye","posture":"true branded ultra (nearest) - 7 villas incl. overwater Casa Ventanas, all-inclusive, houseman service, celebrity hideaway","price_tier":"ultra","rate_note":"~US$1,395-3,195/night meals incl., 4-night min","earning":"Fora / host-Virtuoso lane - commission on application","mor":"commissionable only where offered; no net-rate resale","source":"https://www.mrandmrssmith.com/luxury-hotels/cayo-espanto"},{"name":"Placencia peninsula (Itz''ana / Naia + peers)","location":"mainland-south Belize","posture":"alternate ultra/luxury base; 3-day Ragga sail ends near Placencia so Caulker+Placencia chain naturally","price_tier":"ultra/luxury","earning":"Fora / host-Virtuoso - on application","mor":"no net-rate resale","source":"https://www.raggasailadventures.com/"},{"name":"Caye Caulker on-island","posture":"STRAIGHT: NO branded ultra on-caye; ceiling = comfortable boutique guesthouse (Iguana Reef Inn / Weezie''s); sell as day/character add to an Ambergris or Placencia ultra base","price_tier":"premier (ceiling)","earning":"n/a for ultra","mor":"no net-rate resale","source":"https://www.thoroughlytravel.com/hotels-caye-caulker/"}],"source_verified":"2026-07-06","hero":{"query":"Caye Caulker, Belize"},"geo":{"lat":17.7444,"lng":-88.025}}'::jsonb, 10),
  ('cozumel-mexico', '10S', 'Cozumel', 'Mexico', 'Cozumel drift diving', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"diveglobal","liveaboard","ocean"}', '{}', '{"essential","comfort","premier"}', null, null, '{"key_facts":["Reefs sit on the Mesoamerican Barrier Reef (Great Mayan Reef); drift diving averages ~1.5 knots","Signature walls: Palancar (accessible), Santa Rosa (expert), Columbia Deep","Parque Nacional Arrecifes de Cozumel reef bracelet = MX$220 (~US$13) per person per day (Jan 2026)","Multiple recompression chambers on-island: SSS/Int''l Hospital + Costamed (DAN preferred provider)","Banco Chinchorro (largest W-hemisphere atoll) is ~30-35 nm off Costa Maya, launched from Xcalak/Mahahual - NOT Cozumel"],"safety":{"emergency":"911","hospital":"Costamed / Cozumel International / Medica San Miguel / General Hospital (town); serious trauma to Cancun private hospitals or US air-evac","recompression_chambers":[{"name":"SSS Recompression Chamber / Medicina Hiperbarica Integral","address":"Calle 5 Sur #21-B, Centro, Cozumel QR 77600","phone":"+52 (987) 872-1430 / 872-2387","emergency_24h":"(987) 103-5524","network":"IDAN Referral Center / UHMS / EUBS"},{"name":"Costamed Hyperbaric Center (Cozumel Medical Center)","opened":"Nov 2013","network":"DAN Recompression Chamber Network Preferred Provider"}],"dan_emergency":"+1-919-684-9111","advisory_level":"L2","malaria":"extremely low / none in tourist zone","dengue":"active - Quintana Roo among highest-activity states 2026; chikungunya/Zika also circulate","water":"bottled/purified only","hurricane":"Jun-Nov (peak Aug-Oct)","dive_no_fly":"12h single / 18h multi-day / 24h deco (DAN); use 24h conservative given repetitive day-boat profiles","drift_diving":"briefing required; SMB; dive within cert; Santa Rosa Wall expert-only","chinchorro":"no chamber at atoll; nearest chambers hours away on mainland/Cozumel - extra-conservative profiles + DAN cover","fcdo":{"posture":"AREA-RESTRICTED","quo