  ('mahahual-mexico', '10S', 'Mahahual (Costa Maya & Banco Chinchorro)', 'Mexico', 'The largest coral atoll in the Northern Hemisphere', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"liveaboard","diveglobal"}', '{}', '{"comfort","premier"}', null, 'anchor', '{"key_facts":["Banco Chinchorro - largest coral atoll in the Northern Hemisphere; biosphere 144,000 ha; ~25x10 mi","~80-90 min (some ops ~2.5h) boat from Mahahual; ~200 shipwrecks; permit-restricted (op handles permit)","Best viz May-Sep (~15-30m); crocodile-encounter season Jun 1-Sep 30 (XTC = sole federal permit)","Overnight = palafito stilt-hut on Cayo Centro (legalized 2010; no services) - the liveaboard-style product","Costa Maya cruise port (2nd-largest in Caribbean Mexico, up to ~20k cruisers) = OUT of TWW cruise scope"],"safety":{"emergency":"911","dan_emergency":"+1-919-684-9111","advisory_level":"L2","nearest_chamber":"Costamed, COZUMEL (DAN-certified) - Mahahual clinic has NO chamber; long medevac from Chinchorro","nearest_trauma":"Chetumal (Hospital General, south) or evac to Cancun","malaria":"NONE in tourist zone; dengue present","water":"bottled/purified","hurricane":"Jun-Nov, peak Aug-Oct","dive_no_fly":"18-24h (DAN)","special_rule":"REMOTE-MEDEVAC - dive conservative; permitted+certified op only; croc encounter handler-led, max 6/trip","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dive peak May-Sep (viz ~15-30m; croc encounter hard window Jun 1-Sep 30)","shoulder":"Apr and Oct edges","green":"Nov-Mar (wind/swell; Chinchorro often blown out - fall back to Costa Maya/Xcalak reef)","booking_lead":"4-6 months for permit-limited summer Chinchorro/croc product (permit scarcity = longer lead than a general reef trip)","off_season_specials":"winter Nov-Mar: Costa Maya/Xcalak mainland-reef dive days + no-fly beach fill-the-beds (lean Xcalak, south of the cruise port)","event_peaks":"croc window Jun 1-Sep 30; (Costa Maya cruise day-crowds peak Sep-Dec, busiest Nov, Wed/Thu - OUT of TWW scope, plan dive departures around it)","campaign_start":"live by Dec-Jan, ~4-6 months ahead of the May-Sep dive window; run a winter Xcalak-reef value campaign for Nov-Mar fill-the-beds"},"jewels":[{"name":"Chinchorro overnight palafito expedition (Cayo Centro)","si_tag":"Dive Liveaboards","status":"live","bookable_category":"multi-day dive expedition","tier":"premier","source":"https://pepedivemahahual.com/en/diving/chinchorro/","timing":"Dive peak May-Sep","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"multi-day dive with stilt-hut overnight on the atoll ·","si":"liveaboard","blurb":"multi-day dive with stilt-hut overnight on the atoll ·","when":"Dive peak May-Sep","commission":"on application (liveaboard-reseller/dive-op host)"},{"name":"~200-wreck atoll dives","si_tag":"Dive Liveaboards","status":"live","bookable_category":"wreck/wall diving","tier":"premier","source":"https://xtcdivecenter.com/chinchorro/","timing":"Dive peak May-Sep","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"Dive peak May-Sep","commission":"dive-op host ~10-20% / on application"},{"name":"Chinchorro day-boat 2-3 tank + Cayo Centro","si_tag":"Dive Globally","status":"live","bookable_category":"day dive charter","tier":"comfort","source":"https://xtcdivecenter.com/chinchorro/","timing":"Dive peak May-Sep","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"state day-trip, 2-tank $275 / 3-tank $325, Cayo Centro surface stop ·","si":"diveglobal","blurb":"state day-trip, 2-tank $275 / 3-tank $325, Cayo Centro surface stop ·","when":"Dive peak May-Sep","commission":"dive-op host / affiliate"},{"name":"Costa Maya / Xcalak reef diving","si_tag":"Dive Globally","status":"live","bookable_category":"day dive charter","tier":"comfort","source":"https://amigosdelmar.net/","timing":"Dive peak May-Sep","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","when":"Dive peak May-Sep","commission":"dive-op host ~10-20%"},{"name":"Wild American-crocodile in-water encounter (XTC)","si_tag":"Global Expedition Adventures","status":"future","bookable_category":"expert-guided wildlife","tier":"premier","source":"https://xtcdivecenter.com/crocs/croc-encounters/","timing":"Dive peak May-Sep","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"handler-led encounter, world''s only permitted such experience ·","si":"expedition","blurb":"handler-led encounter, world''s only permitted such experience ·","when":"Dive peak May-Sep","commission":"dive-op host / on application; XTC sole permit"}],"faq":[{"q":"What''s the real risk to plan for diving Mahahual?","a":"Remote medevac - the load-bearing risk. Mahahual has NO hyperbaric chamber; the nearest DAN-certified chamber is in Cozumel, a multi-hour transit from a Chinchorro site ~25 miles offshore. Dive conservatively, hold no-fly 18-24h, and treat DCS as a logistics problem.","source":"costamed.com.mx","si_tag":"safety"},{"q":"When is the best time to dive Mahahual and Chinchorro?","a":"May-September - the counterintuitive answer: calmest seas, best visibility (~15-30m) and the crocodile season (Jun 1-Sep 30), even though it overlaps the rainy/hurricane months. Winter (Nov-Mar) sees more wind and Chinchorro is often blown out.","source":"coralrealm.com","si_tag":"diveglobal"},{"q":"Can I day-dive Banco Chinchorro, and how?","a":"Yes - most Mahahual/Xcalak operators run day-trips for certified divers: a 2-tank ($275) or 3-tank ($325) day with a Cayo Centro stop, an 80-90-minute crossing each way. The operator handles the limited federal permit when you book; May-September has the calmest seas.","source":"xtcdivecenter.com","si_tag":"diveglobal"},{"q":"Can you really swim with wild crocodiles at Chinchorro?","a":"Yes - it''s the only legally permitted in-water wild-crocodile encounter on Earth, and only XTC Dive Center holds the federal permit. The season is a hard window of June 1 to September 30, capped at 6 people (2 in the water with the handler at a time), flotation device required. Book far ahead.","source":"xtcdivecenter.com","si_tag":"globaladv"},{"q":"What is the Banco Chinchorro liveaboard experience actually like?","a":"It''s a stilt-hut expedition, not a cruise ship. Multi-day trips overnight in a palafito on Cayo Centro - a basic 2x2m stilt-deck fishing hut with hammocks and no services - legalized in 2010. It''s the closest access to the remote walls and ~200 wrecks; permit-scarce, so book the specialist operator well ahead.","source":"pepedivemahahual.com","si_tag":"liveaboard"}],"seo":{"meta_title":"Mahahual & Banco Chinchorro: Atoll Diving Guide","meta_description":"Mahahual is the gateway to Banco Chinchorro - the Northern Hemisphere''s largest coral atoll: ~200 wrecks, croc encounters, and the remote-chamber realities.","slug":"mahahual-mexico","primary_keyword":"Banco Chinchorro diving","long_tail":["Mahahual Banco Chinchorro dive","Chinchorro liveaboard palafito","Chinchorro crocodile snorkel XTC","Costa Maya diving","Xcalak scuba diving"],"search_language":"es","local_keywords":["buceo Banco Chinchorro","Mahahual buceo Costa Maya","encuentro con cocodrilos Xcalak","buceo Xcalak","atolon Chinchorro liveaboard palafito"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister - commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":{"bin":"freely_bookable","level":"L2","codes":[],"consent_flow":false,"note":"Quintana Roo US L2 (Exercise Increased Caution, dated 2026-05-29) - freely bookable; the real planning is dive-medevac (nearest chamber Cozumel), not crime; MXN currency, dive prices often USD-quoted"},"si_checklist_25":{"run_date":"2026-07-30","hits":4,"misses":18,"disregarded":3,"note":"Canonical 25-SI list; Banco Chinchorro moat = largest N-Hemisphere atoll (~200 wrecks) + sole permitted wild-crocodile encounter (XTC); sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"liveaboard","name":"liveaboard","status":"live","note":"overnight-palafito multi-day on Cayo Centro (stilt-hut, not a cruise ship)"},{"si":"diveglobal","name":"diveglobal","status":"live"}],"ultra":[{"name":"Private crewed Chinchorro dive charter / private palafito buy-out","why_ultra":"exclusive-use permitted multi-day atoll expedition - the rarest dive product in Mexican waters (permit-scarce, ~200 wrecks, sole-group access)","earning":"on application (dive-op/charter host / liveaboard-reseller)","virtuoso_value_add":"none formal (specialist dive charter, not a consortia hotel)","mor":"commission-on-net, agent-of-record; no net-rate resale"},{"name":"Nearest branded ultra = Riviera Maya (Mayakoba: Rosewood/Banyan Tree; Maroma A Belmond)","why_ultra":"n/a locally - branded-residence ultra sits far north; route ultra client Mahahual-for-dive + Riviera-Maya-for-stay","earning":"via host-Virtuoso (see Playa del Carmen / Puerto Morelos dossiers)","virtuoso_value_add":"upgrade / breakfast / resort credit (per those dossiers)","mor":"commission-on-net"}],"source_verified":"2026-07-04","hero":{"query":"Mahahual (Costa Maya & Banco Chinchorro), Mexico"},"geo":{"lat":18.7167,"lng":-87.7167}}'::jsonb, 21),
  ('osa-peninsula-corcovado-costa-rica', '10S', 'Osa Peninsula / Corcovado', 'Costa Rica', 'Corcovado rainforest at the continent''s edge', 'live', 'verified', 'mountainValley', 'Costa Rica', '{"expedition","diveglobal"}', '{}', '{"comfort","premier","ultra"}', null, null, '{"key_facts":["Corcovado holds 2.5% of the world''s biodiversity in 41,800 hectares — ''the most biologically intense place on Earth'' (National Geographic)","Certified guide LEGALLY MANDATORY for all Corcovado entry (SINAC rule since Feb 1 2014)","Caño Island is Costa Rica''s #2 dive site (after Cocos), 30–100+ ft viz, capped at 120 visitors/day","Cocos Island = liveaboard-only pilgrimage, ~36-hr sail from Puntarenas, world''s most consistent schooling hammerheads","Golfo Dulce is one of only four tropical fjords on Earth and hosts BOTH hemispheres'' humpback populations"],"safety":{"emergency":"911","advisory_level":"L2","book_enabled":true,"air_access_verified":true,"air_access":"SJO → Drake Bay (DRK) / Puerto Jiménez (PJM) daily small-strip flights (~40–45 min); or 6–8 hr overland 4×4 drive","remote_flag":true,"medevac_note":"Deep-rural; nearest clinic Puerto Jiménez → San José for major care; Sirena has no road; Cocos ~36 hr by sea","hazards":["tide-timed river crossings (crocodile + bull shark at Rio Sirena/Rio Claro mouths)","jungle heat/humidity","Pacific rip currents","venomous snakes (fer-de-lance)","no-fly-after-diving (Caño + Cocos)"],"malaria":"low but present in region; Corcovado itself generally not a malaria concern — consult travel clinic","dengue":"primary mosquito risk; spikes May–Nov rainy season (CR 31,000+ cases 2024)","water":"potable in serviced areas; follow lodge guidance in deep-Osa","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-08-19","page_updated":"2026-05-19T11:42:25+01:00"}},"timing":{"terrestrial_peak":"mid-Dec–Apr (dry, Corcovado access best)","green_season":"May–Nov (lush, some lodge closures, access degrades)","whale_season":"Jul–Nov Southern humpback (prime late Aug–Sep) + Nov–Feb Northern humpback","cocos_hammerhead_peak":"Jun–Dec","curve_start":"early-mid December","fire_date":"late November (curve-start − 1–2 wks); secondary early-July for whale+hammerhead","booking_lead":"eco-lodges 3–6 mo; Sirena permits 3–4 mo; Cocos liveaboard 6–18 mo","sharpen_note":"sharpen on live tracking — windows drift year to year"},"jewels":[{"name":"Sirena Ranger Station, Corcovado","si_tag":"expedition","highlight":"tapir ~70% overnight, all 4 monkey species, scarlet macaw near-guaranteed, peccary herds 30+","tier":"premier","source":"https://vamosrentacar.com/blog/corcovado-national-park-sirena-station/","si":"expedition","commission":"guided trek + Sirena overnight via DMC; margin on guide service"},{"name":"Caño Island Biological Reserve","si_tag":"diveglobal","highlight":"CR #2 dive site, 30–100+ ft viz, sharks/rays/turtles, 120-pax/day cap","tier":"premier","source":"https://www.entercostarica.com/attractions/national-parks-and-refuges/cano-island","si":"diveglobal","commission":"day-dive/snorkel net-rate/referral"},{"name":"Cocos Island National Park (UNESCO)","si_tag":"diveglobal","highlight":"world''s most consistent schooling hammerheads; liveaboard-only, 36-hr sail from Puntarenas","tier":"ultra","source":"https://www.aggressor.com/destination/Cocos","si":"diveglobal","commission":"own CLIA/DLA lane (Aggressor/Undersea Hunter)"},{"name":"Golfo Dulce (tropical fjord)","si_tag":"WILDLIFE_NATURE/RHN","highlight":"one of 4 tropical fjords on Earth; both hemispheres'' humpbacks; dolphins, mangroves","tier":"premier","source":"https://www.nicuesalodge.com/blog/witness-the-wonder-humpback-migration-in-costa-ricas-golfo-dulce","si":"WILDLIFE_NATURE/RHN","commission":"lodge-bundled boat tour"},{"name":"Drake Bay","si_tag":"DIVE/GEA","highlight":"northern-Osa gateway to Caño Island + Corcovado San Pedrillo; sportfishing, night tours","tier":"comfort","source":"https://www.copadearbol.com/osa-peninsula-eco-lodge/","si":"DIVE/GEA","commission":"lodge + activity referral"},{"name":"Puerto Jiménez","si_tag":"expedition","highlight":"frontier town + PJM airstrip; Golfo Dulce + southern Corcovado gateway","tier":"comfort","source":"https://mytanfeet.com/driving-in-costa-rica/puerto-jimenez-osa-peninsula/","si":"expedition","commission":"gateway nights + transfers"},{"name":"Matapalo surf & waterfalls","si_tag":"expedition","highlight":"secluded breaks + jungle cascades at peninsula tip","tier":"comfort","source":"https://www.crsurfzone.com/corcovado-national-park.html","si":"expedition","commission":"lodge-bundled excursion"},{"name":"Whale-watching, Golfo Dulce","si_tag":"WILDLIFE_NATURE","highlight":"both hemispheres'' humpbacks (Jul–Nov Southern + Nov–Feb Northern)","tier":"premier","source":"https://www.nicuesalodge.com/blog/witness-the-wonder-humpback-migration-in-costa-ricas-golfo-dulce","si":"wildlife","commission":"guided boat referral"},{"name":"Cacao finca / farm-to-bar chocolate","si_tag":"expedition","highlight":"Indigenous + smallholder cacao experience","tier":"comfort","source":"https://www.osawild.travel/locations/","si":"expedition","commission":"referral"}],"faq":[{"q":"Do you need a guide to hike Corcovado National Park?","a":"Yes — a certified guide is legally mandatory for all Corcovado entry, a SINAC rule in force since February 1, 2014 and enforced at every ranger station, where unguided visitors are turned away. Build the guided-trek product; there is no compliant self-guided version to sell.","source":"Wikipedia — Corcovado National Park, 2026-07-06","si_tag":"expedition"},{"q":"Can you dive Cocos Island on a day trip?","a":"No. Cocos is liveaboard-only — it lies ~342 mi off the Pacific coast, an ~36-hr open-ocean crossing from Puntarenas, and is sold as 8/10/12-night charters (15/21/27 dives) via Aggressor or Undersea Hunter. Berths book 6–18 months out, so plan far ahead.","source":"aggressor.com, 2026-07-06","si_tag":"diveglobal"},{"q":"Are the Osa eco-lodges right for a honeymoon?","a":"Yes — the Osa is honeymoon-grade seclusion without the resort cliché: private-reserve bungalows over the Pacific, canopy suites and no Wi-Fi. Lapa Rios alone offers 16 ocean-view bungalows across 1,000 protected acres, and remote lodges bundle meals, guided excursions and transfers by necessity.","source":"laparios.com, 2026-07-06","si_tag":"romance"},{"q":"When can you see whales in Golfo Dulce?","a":"Golfo Dulce — one of only four tropical fjords on Earth — draws both hemispheres'' humpbacks, so the season is unusually long: Southern-hemisphere humpbacks calve July–November (prime late Aug–Sept), and Northern-hemisphere humpbacks arrive November–February.","source":"nicuesalodge.com, 2026-07-06","si_tag":"wildlife"},{"q":"What''s the real risk to plan for on a Corcovado trek?","a":"The tide-timed river crossings. Rio Sirena and Rio Claro are the most dangerous, with American crocodiles and bull sharks patrolling the river mouths, so guides cross only at low tide and never in storms. This — plus jungle heat and deep-remote medevac — is the true gatekeeper, above petty crime.","source":"crsurfzone.com, 2026-07-06","si_tag":"safety"},{"q":"Is diving Cocos Island dangerous?","a":"It is advanced diving in a strong-current, deeply remote environment. DAN membership and dive insurance are essential, no-fly-after-diving surface intervals apply, and because the site is ~36 hr from land the vessel itself is the only evacuation. Not a first-timer''s trip.","source":"aggressor.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Osa Peninsula & Corcovado, Costa Rica — The Most Biologically Intense Place on Earth | TravelWell.World","search_language":"es-CR","local_keywords":["Parque Nacional Corcovado","Península de Osa","Isla del Coco buceo","Bahía Drake","Golfo Dulce ballenas","Puerto Jiménez"],"long_tail_en":["Corcovado guided tour","Sirena station Corcovado","Caño Island diving Drake Bay","Cocos Island liveaboard hammerhead","Osa Peninsula luxury eco lodge","Golfo Dulce whale watching"],"hreflang":["en","es-CR"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06"},"booking":null,"si_checklist_25":null,"sis_present":["expedition","diveglobal"],"ultra":[{"name":"Lapa Rios","operator":"Böëna / Cayuga Collection","location":"above Corcovado","earn":"Virtuoso/consortia; AoR via ST Costa Rica DMC","tier":"ultra"},{"name":"El Remanso","location":"Puerto Jiménez / private beach","earn":"Virtuoso/consortia + full-property buyout","tier":"ultra"},{"name":"Copa de Árbol","location":"Drake Bay","earn":"consortia","tier":"ultra"},{"name":"Playa Cativo","location":"Golfo Dulce","earn":"consortia + private-reserve buyout","tier":"ultra"},{"name":"Aguila de Osa","location":"Drake Bay","earn":"consortia + Caño Island dive referral","tier":"ULTRA/PREMIUM"},{"name":"Cocos private liveaboard charter","operator":"Aggressor / Undersea Hunter","earn":"own CLIA/DLA lane — AoR/MoR via DLA relationship","tier":"ultra"},{"name":"Kasiiya Papagayo","correction":"in GUANACASTE, not Osa — do not sell as Osa property","tier":"N/A"}],"source_verified":"2026-07-06","hero":{"query":"Osa Peninsula / Corcovado, Costa Rica"},"geo":{"lat":8.54,"lng":-83.59}}'::jsonb, 22),
  ('peninsula-valdes-argentina', '10S', 'Península Valdés & Puerto Madryn, Argentina', 'Argentina', 'Patagonian steppe thrust into the Atlantic', 'live', 'verified', 'mountainValley', 'Patagonia & The Lakes', '{"expedition","romance","liveaboard","wildlife"}', '{}', '{"essential","comfort","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","advisory_level":"L1","advisory_updated":"2026-05-20","advisory_source":"https://travel.state.gov/content/travel/en/traveladvisories/traveladvisories/argentina-travel-advisory.html","regional_caveat":"Rosario L2 (~1,300 km away, not this destination)","book_enabled":true,"bin":"freely bookable (L1)","consent_flow":false,"air_access_verified":true,"air_access":"PMY (Puerto Madryn / El Tehuelche) & REL (Trelew) via Buenos Aires AEP on Aerolíneas Argentinas / Flybondi / JetSMART","remote_flag":true,"water_potable":true,"notes":["cold-water no-fly diving","wind/exposure on steppe","gravel-road self-drive on peninsula","trauma evac to Buenos Aires"],"fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/argentina","read":"2026-08-19","page_updated":"2026-05-07T17:26:11+01:00"}},"timing":{"governed_by":"wildlife_seasonality","windows":{"southern_right_whales":{"range":"Jun–mid-Dec","peak":"Sep–Oct","where":"Puerto Pirámides"},"orca_beaching_attack":{"range":"Mar–Apr (primary) + some Oct–Nov","peak":"end-Mar–early-Apr","where":"Punta Norte"},"magellanic_penguins":{"range":"Sep–Mar","peak":"Oct–Nov","where":"Punta Tombo"},"elephant_seals":{"range":"Aug–Nov combat; pupping mid-Dec–Feb","peak":"Sep–Nov","where":"Caleta Valdés"}},"peak":"whale season Sep–Oct (broad-overlap sweet spot)","inflection":["late-Feb–early-Apr (orca chasers)","Nov (whale taper + penguin chicks + warm dive water)"],"fire_date":"curve-start minus 1–2 weeks — whale inventory mid-to-late May; orca packages late Feb; penguin day-trips late Aug","off_season_fill":"May (pre-whale calm) and Dec–Feb (penguin chicks + warmest diving + elephant-seal pupping)"},"jewels":[{"name":"Puerto Pirámides whale-watch (Southern right whales)","si_tag":"expedition","window":"Jun–mid-Dec, peak Sep–Oct","tier":"comfort","source":"https://www.puertopiramides.gov.ar/whales-season/","hook":"The signature. Boats from the only nautically-authorized whale port in Argentina; forty-tonne females with calves feet from the hull","si":"expedition","blurb":"The signature. Boats from the only nautically-authorized whale port in Argentina; forty-tonne females with calves feet from the hull","commission":"activity / DMC bundle"},{"name":"Punta Norte orca beaching-attack","si_tag":"expedition","window":"Mar–Apr (never guaranteed)","tier":"comfort","source":"https://peninsulavaldes.com/wildlife/orcas","hook":"Cliff-top watch for orcas deliberately stranding to take sea-lion pups — one of the rarest predatory spectacles on the planet","si":"expedition","blurb":"Cliff-top watch for orcas deliberately stranding to take sea-lion pups — one of the rarest predatory spectacles on the planet","commission":"DMC / specialist wildlife operator"},{"name":"Caleta Valdés elephant seals","si_tag":"expedition","window":"Aug–Nov combat; pupping Dec–Feb","tier":"comfort","source":"https://peninsulavaldes.com/wildlife/sea-elephant","si":"expedition","commission":"DMC circuit / activity"},{"name":"Punta Tombo Magellanic penguins","si_tag":"expedition","window":"Sep–Mar, chicks Oct–Nov","tier":"comfort","source":"https://www.interpatagonia.com/puertomadryn/penguins-punta-tombo.html","si":"expedition","commission":"DMC day-trip / activity"},{"name":"Puerto Madryn sea-lion dive (Punta Loma)","si_tag":"Dive/OCA","window":"year-round; best Sep–Oct water","tier":"comfort","source":"https://www.civitatis.com/en/puerto-madryn/sea-lion-dive/","hook":"Dive among wild sea lions — a top-handful global experience","si":"Dive/OCA","blurb":"Dive among wild sea lions — a top-handful global experience","commission":"dive-operator activity"},{"name":"Golfo Nuevo wreck cluster (Folias/Miralles/Albatros)","si_tag":"Dive/OCA","window":"year-round (cold, no-fly)","tier":"comfort","source":"https://travel.padi.com/dive-trip/puerto-madryn/sea-lions-dive-ship-wreck-12594/","timing":"whale season Sep–Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Sunken cargo ships as artificial reef — octopus, sea stars, fish schools; cold-water, no-fly","si":"Dive/OCA","blurb":"Sunken cargo ships as artificial reef — octopus, sea stars, fish schools; cold-water, no-fly","when":"whale season Sep–Oct","commission":"dive-operator activity"},{"name":"Isla de los Pájaros birding","si_tag":"Wildlife & Nature (future)","window":"year-round","tier":"essential","source":"https://peninsulavaldes.com/travel-guide/gaiman/gaiman-the-welsh-colony-the-ultimate-guide","timing":"whale season Sep–Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Protected bird island viewed from a shoreline hide — herons, cormorants, migratory shorebirds","si":"Wildlife & Nature (future)","blurb":"Protected bird island viewed from a shoreline hide — herons, cormorants, migratory shorebirds","when":"whale season Sep–Oct","commission":"DMC circuit add-on"},{"name":"Kayak with sea lions","si_tag":"Wildlife & Nature (future)","window":"spring–summer","tier":"comfort","source":"https://www.civitatis.com/en/puerto-madryn/sea-lion-dive/","si":"Wildlife & Nature (future)","commission":"activity"},{"name":"Gaiman Welsh-Patagonian afternoon tea","si_tag":"culture add-on","window":"year-round","tier":"essential","source":"https://www.interpatagonia.com/gaiman/welsh-tea-gaiman.html","timing":"whale season Sep–Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Casa de té tradition in a living Welsh colony; pairs naturally with a Punta Tombo day","si":"culture add-on","blurb":"Casa de té tradition in a living Welsh colony; pairs naturally with a Punta Tombo day","when":"whale season Sep–Oct","commission":"DMC day-trip inclusion"}],"faq":null,"seo":{"meta_title":"Península Valdés & Puerto Madryn Argentina — Whales, Orcas & Penguins | TravelWell","search_language":"es-AR","local_keywords":["Península Valdés ballenas","avistaje de ballenas Puerto Madryn","orcas Punta Norte","Punta Tombo pingüinos","elefantes marinos Caleta Valdés","buceo con lobos marinos Puerto Madryn","té galés Gaiman"],"hreflang":["en","es-AR"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07"},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Estancia Rincón Chico","tier":"ultra","why":"20km private peninsula coastline, 8 rooms, no outside visitors, NatGeo Traveller top-10 LatAm lodge","earning":"MoR / consortia-preferred FIT","mor_rung":true,"source":"https://rinconchico.com.ar/"},{"name":"Hotel Territorio","tier":"premium design 4★","why":"concrete-and-wood boutique, 36–38 rooms facing Golfo Nuevo, best-in-town whale-season base","earning":"MoR / bedbank / consortia","mor_rung":true,"source":"https://www.greatsmallhotels.com/puerto-madryn-boutique-hotels/hotel-territorio"},{"name":"Faro Punta Delgada","tier":"premium character / upper-mid","why":"100-year working lighthouse-estancia, 27 rooms, remote southern tip, elephant seals below cliff","earning":"MoR / DMC net","mor_rung":true,"source":"https://www.swoop-patagonia.com/argentina/peninsula-valdes/hotels/faro-punta-delgada"}],"source_verified":null,"hero":{"query":"Península Valdés & Puerto Madryn, Argentina, Argentina"},"geo":{"lat":-42.5,"lng":-64}}'::jsonb, 23),
  ('placencia-belize', '10S', 'Placencia', 'Belize', 'Whale sharks and mainland sand', 'live', 'verified', 'oceanAerial', 'Belize', '{"liveaboard","expedition","diveglobal","ocean","wildlife","culture"}', '{}', '{"essential","comfort","premier"}', null, null, '{"key_facts":["Placencia is Belize''s southern beach peninsula with the country''s best mainland beaches and its main resort/romance-wedding coast.","Gladden Spit, off Placencia, is the world''s most predictable whale-shark aggregation, timed to the Mar-Jun full moons (peak Apr-May).","The southern barrier reef (Silk Cayes, Laughing Bird Caye NP, South Water Caye) launches from Placencia; the outer atolls are reachable.","Monkey River (howler monkeys, manatees) and the Cockscomb Basin (world''s first jaguar preserve) are easy day trips.","Access is BZE -> PLJ (Placencia airstrip) by 20-30 min puddle-jumper on Tropic Air / Maya Island Air; ~3.5-4 hr drive alternative."],"safety":{"emergency":"911 (Belize national; verify on arrival)","hyperbaric_chamber":"Nearest chambers on Ambergris Caye (San Pedro): SSS Network 24/7 226-2851; Belize Chamber Project 24/7 226-2660 — DISTANCE FLAG from southern reef, plan conservative profiles","hospital":"No peninsula trauma center; Placencia/Dangriga clinics stabilize; serious trauma evacuates to Belize City","book_enabled":true,"consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for the country (level + reason + named-danger areas + complete ''If you decide to travel'' guidance), pulled live, plus traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"},"l3_disclosure":true,"advisory_reissued":"2026-06-18","advisory_codes":"C (Crime) only","state_dept_carveout":"only Southside Belize City restricted; Placencia open","stay_in_zone":true,"air_access_verified":"BZE -> PLJ (Placencia) by puddle-jumper (Tropic Air / Maya Island Air), 20-30 min","water":"bottled / purified only","dengue":"endemic seasonal mosquito-borne risk; repellent advised","malaria":"low/localized rural risk; negligible in tourist zone"},"timing":{"peak":"late-Dec-Apr (dry season; highest rates, biggest crowds)","whale_shark_event_peak":"Apr-May around the full moons (distinct, separate peak); 2026 full moons Mar 14 / Apr 13 / May 12 / Jun 11; windows Mar 12-24, Apr 11-23, May 10-22, Jun 9-21","shoulder_green":"Sep-Nov (green season; better value, hurricane exposure Jun-Nov)","events":"Placencia Lobsterfest ~late June (confirm 2026 date)","booking_window_lead_time":"whale-shark Apr/May 3-4 months; dry-season peak 3-4 months; shoulder 4-6 weeks","fill_the_beds":"green season lead with Monkey River, Cockscomb jaguar preserve, Hopkins Garifuna, reef days, year-round flats fly-fishing","campaign_start_trigger":"whale-shark push fires early-mid Feb 2026; dry-season peak fires late-Sep/Oct 2025; green-season value fires Jun-Jul","fire_date":"2026-02-10"},"jewels":[{"name":"Gladden Spit whale sharks (Apr-May full moons)","si_tag":"Dive Liveaboards","status":"live","tier":"premier","hook":"Snorkel or dive the world''s most predictable whale-shark aggregation, 90 min offshore.","bookable_category":"licensed whale-shark dive/snorkel","source":"https://splashbelize.com/belize-scuba-diving-sites/whale-sharks-at-gladden-spit/","si":"liveaboard","blurb":"Snorkel or dive the world''s most predictable whale-shark aggregation, 90 min offshore.","commission":"dive-operator direct — David''s CLIA lane, affiliate -> commissioned-agent 12-18%; reserve fee pass-through"},{"name":"Silk Cayes snorkel / dive","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Postcard barrier-reef cayes with turtles, sharks, rays and eels.","bookable_category":"reef snorkel/dive day","source":"https://splashbelize.com/belize-scuba-diving-sites/whale-sharks-at-gladden-spit/","si":"diveglobal","blurb":"Postcard barrier-reef cayes with turtles, sharks, rays and eels.","commission":"dive-operator direct / affiliate; reserve fee pass-through"},{"name":"Laughing Bird Caye National Park","si_tag":"Ocean Adventures","status":"future","tier":"essential","hook":"Tiny faro-reef caye 11 nm east; easy family snorkel/dive.","bookable_category":"reef day-trip","source":"https://splashbelize.com/belize-scuba-diving-sites/whale-sharks-at-gladden-spit/","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Tiny faro-reef caye 11 nm east; easy family snorkel/dive.","when":"late-Dec-Apr","commission":"affiliate 4-8% / operator direct; park fee pass-through"},{"name":"Monkey River howler-monkey + manatee watch","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"Boat + river cruise + jungle hike into howler habitat; manatees on the return.","bookable_category":"guided river/wildlife tour","source":"https://blueturtleplacencia.com/placencia-adventure-tours/monkey-river-tour","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Boat + river cruise + jungle hike into howler habitat; manatees on the return.","when":"late-Dec-Apr","commission":"DMC (Barefoot) AOR / affiliate; village fee pass-through"},{"name":"Cockscomb Basin jaguar-preserve day trip","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"World''s first jaguar reserve — 128,000 acres of trails, waterfalls, birds.","bookable_category":"guided day trip","source":"https://en.wikipedia.org/wiki/Cockscomb_Basin_Wildlife_Sanctuary","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wildlife","blurb":"World''s first jaguar reserve — 128,000 acres of trails, waterfalls, birds.","when":"late-Dec-Apr","commission":"DMC AOR / affiliate; sanctuary entry pass-through"},{"name":"Garifuna Coast — Hopkins day trip","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Drumming, culture and beaches of the Garifuna village of Hopkins.","bookable_category":"cultural day trip","source":"https://www.hamanasi.com/belize-vacation/cockscomb-jaguar-preserve-tour/","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Drumming, culture and beaches of the Garifuna village of Hopkins.","when":"late-Dec-Apr","commission":"DMC AOR / affiliate"},{"name":"Flats fly-fishing (permit / bonefish / tarpon)","si_tag":"Ocean Adventures","status":"future","tier":"premier","hook":"World-class permit water on the southern flats, year-round.","bookable_category":"guided fly-fishing","source":"https://www.jmbelizetravel.com/placencia-sea-tours/","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"World-class permit water on the southern flats, year-round.","when":"late-Dec-Apr","commission":"fishing-lodge/guide direct; affiliate on packaged trips"},{"name":"Placencia sidewalk + fishing village","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"The famous narrow sidewalk, seafood shacks and end-of-peninsula soul.","bookable_category":"self-guided","source":"https://chabilmarvillas.com/","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"The famous narrow sidewalk, seafood shacks and end-of-peninsula soul.","when":"late-Dec-Apr","commission":"none (drives F&B + lodging attach)"}],"faq":[{"q":"Is Placencia good for a honeymoon or wedding?","a":"Yes — it is Belize''s most credible mainland resort/romance market, with real luxury-to-ultra range. Naïa Resort & Spa (39 beach houses + treetop villas on 224 private acres, mile of beach, from ~US$380/night) and SLH-member Itz''ana anchor the beachfront, plus true private-island elopements offshore. The peninsula earns both the wedding and the dive log.","source":"naiaresortandspa.com, 2026-07-06","si_tag":"romance"},{"q":"When can you swim with whale sharks in Placencia?","a":"Around the Mar–Jun full moons at Gladden Spit — the one place on the planet where whale-shark arrival is \"reasonably predictable.\" 2026 full moons are Mar 14, Apr 13, May 12 and Jun 11, with windows ~2 days before to ~10 days after; April and May fill first, so serious divers book three to four months ahead. Encounters are not guaranteed — you''re buying the window.","source":"splashbelize.com, 2026-07-06","si_tag":"liveaboard"},{"q":"What wildlife can you see near Placencia?","a":"Two flagship day trips. The Monkey River eco-tour (a ~45-min coastal boat run then a river cruise) carries you into black-howler-monkey habitat with crocodiles, iguanas, toucans and manatees on the return; and the Cockscomb Basin — the world''s first jaguar preserve, 128,000 acres, est. 1986 — is a half-day inland via Maya Center.","source":"blueturtleplacencia.com, 2026-07-06","si_tag":"expedition"},{"q":"Does Placencia have good beaches and reef?","a":"Yes — the country''s best mainland beaches on a 16-mile peninsula, plus the closest mainland launch to the southern reef. Splash Dive Center''s home waters — the Silk Cayes, South Water Caye and Laughing Bird Caye — are \"postcard perfect islands on the barrier reef\" with turtles, sharks, rays and eels, most a 30–60 minute run out.","source":"splashbelize.com, 2026-07-06","si_tag":"tropical"},{"q":"Can you fly-fish the flats in Placencia?","a":"Yes — the southern flats and river mouths are world-class permit water, fishable year-round for permit, bonefish and tarpon by skiff. It''s a high-value niche booked through Placencia fishing lodges and guides, and a reliable green-season lever when the reef days are between fronts.","source":"jmbelizetravel.com, 2026-07-06","si_tag":"ocean"},{"q":"Is there a destination spa / wellness stay in Placencia?","a":"Yes — Naïa Resort & Spa is built for it: a 224-acre private property with a mile of beach, a destination spa and a private-island couples retreat, strong on both romance and wellness. It''s the anchor for a quiet-beach reset paired with reef or river days.","source":"naiaresortandspa.com, 2026-07-06","si_tag":"wellness"},{"q":"What''s the real risk to plan for in Placencia?","a":"Dive-chamber distance and open-water boat runs, not crime. The nearest recompression chamber is on Ambergris Caye (San Pedro), a meaningful distance north of the southern reef, so plan conservative profiles and no-fly windows; the run to Gladden Spit is ~90 minutes each way with early 6–7am departures. There is no full trauma center on the peninsula — serious cases evacuate to Belize City.","source":"ambergriscaye.com, 2026-07-06","si_tag":"safety"},{"q":"Is swimming with whale sharks dangerous?","a":"It runs guided-only with a permitted operator — Gladden Spit is inside a marine reserve and only permitted operators may run the aggregation, no-touch and no-chase. Snorkelers work the surface aggregation over 2–3 hours (moderate swimming ability needed); divers descend to ~50–80 ft to meet the sharks and must be certified and guided.","source":"flowersvacationrentals.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Placencia, Belize Travel Guide 2026 — Whale Sharks, Beaches & Reef | TravelWell.World","meta_description":"Plan Placencia: the Gladden Spit whale-shark season (Apr-May full moons), Silk Cayes & Monkey River, best mainland beaches, luxury & private-island resorts, straight L3 safety and dive-chamber facts.","slug":"placencia-belize","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06","search_language":"en","primary_keywords":["Placencia Belize travel guide","whale sharks Placencia","Placencia beaches"],"local_keywords":["tiburon ballena Placencia Belice","temporada tiburon ballena Gladden Spit 2026","playas de Placencia","tour Monkey River Placencia","buceo Silk Cayes Placencia","resorts de lujo Placencia"],"hreflang":["en","es"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"liveaboard","status":"live"},{"si":"expedition","status":"live"},{"si":"diveglobal","status":"future"},{"si":"ocean","status":"future"},{"si":"wildlife","status":"future"},{"si":"culture","status":"future"}],"ultra":[{"name":"Itz''ana Resort & Residences","price_tier":"ultra","virtuoso":true,"earning":"on application / host-Virtuoso / SLH trade / Fora","mor_posture":true,"note":"beachfront + marina, Small Luxury Hotels of the World","source":"https://slh.com/hotels/itz''ana-resort-and-residences"},{"name":"Naia Resort & Spa","price_tier":"luxury","virtuoso":true,"earning":"host-agency / Virtuoso AOR","mor_posture":true,"note":"224-acre, mile of beach, destination spa; R&H + Wellness","source":"https://www.naiaresortandspa.com/"},{"name":"Turtle Inn (Coppola Hideaways)","price_tier":"ultra","virtuoso":true,"earning":"Coppola Hideaways trade / host-Virtuoso / Fora","mor_posture":true,"note":"Balinese-inspired thatched beach hideaway near village","source":"https://thecoppolahideaways.com/resort/turtle-inn"},{"name":"Gladden Private Island","price_tier":"ultra","virtuoso":false,"earning":"on application / host-Virtuoso / private-island trade","mor_posture":true,"note":"single-villa caye, helicopter transfer on 7+ nights, whale sharks off-island","source":"https://www.privateislandsonline.com/central-america/belize/gladden-private-island"},{"name":"Ray Caye Island Resort","price_tier":"ultra","virtuoso":false,"earning":"on application / host-Virtuoso / private-island trade","mor_posture":true,"note":"private island on edge of Gladden Spit & Silk Cayes reserves","source":"https://raycaye.com/"},{"name":"Copal Tree Lodge (Muy''Ono, Toledo)","price_tier":"luxury","virtuoso":false,"earning":"Muy''Ono trade / host-Virtuoso / Fora","mor_posture":true,"note":"rainforest all-inclusive luxury lodge near Punta Gorda","source":"https://etichotels.com/journal/top-10-sustainable-hotels-in-belize/"}],"source_verified":"2026-07-06","hero":{"query":"Placencia, Belize"},"geo":{"lat":16.5155,"lng":-88.3665}}'::jsonb, 24),
  ('playa-del-carmen-mexico', '10S', 'Playa del Carmen', 'Mexico', 'Cenotes, Fifth Avenue and the Cozumel ferry', 'live', 'verified', 'venice', 'Quintana Roo (Cancún & Riviera Maya)', '{"romance","expedition","diveglobal","culture"}', '{}', '{"essential","comfort","ultra"}', null, null, '{"key_facts":["Quinta Avenida (Fifth Avenue) is a multi-km pedestrian dining/shopping/nightlife street parallel to the beach.","Cozumel reef wall is a 40-minute ferry away (Xcaret Xailing/Winjet/Ultramar, ~US$32 round trip).","Cenotes Chikin-Ha, Chaak Tun and Eden are within ~30 minutes for swim/snorkel/cavern dives.","Xcaret and Xplor eco-parks (14-line, 3.8 km zipline circuit) sit just outside town.","Best weather is November–March; May–October is hot, humid and rainy."],"safety":{"emergency":"911","hospital":"Hospiten Riviera Maya, Playa del Carmen (+52 984 159 2200); serious trauma escalates to Cancún","advisory_level":"L2","malaria":"none in tourist Quintana Roo","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua State of Sinaloa FCDO advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route State of Tamaulipas FCDO advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed by federal toll road 85D from Monterrey federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways State of Zacatecas FCDO advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro Federal Highway 15D State of Jalisco FCDO advises against all but essential travel to the areas south and south-west of Lake Chapala to the border with the state of Colima."},{"form":"against all but essential travel","text":"advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero State of Colima FCDO advises against all but essential travel to the state of Colima, except the city of Manzanillo accessed by sea or air via the Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Guerrero, except the town of Zihuatanejo/Ixtapa accessed by air."},{"form":"against all but essential travel","text":"advises against all but essential travel to within 40km of the Guatemalan border between the Pacific Coast up to and including the border crossing at Gracias a Dio."},{"form":"against all but essential travel","text":"advises against all but essential travel on Federal Highway 199 (Carretera Federal 199) between Rancho Nuevo (just outside San Cristobal de las Casas) and the Chancalá junction just outside Palenque (where Federal Highway 199 meets Federal Highway 307)."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Acapulco."},{"form":"against all but essential travel","text":"advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border FCDO advises against all but essential travel to the city of Tecate in Baja California, including roads between Tijuana and Tecate."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Chihuahua, except: the city of Chihuahua the border crossing in Ciudad Juárez (accessed by federal toll road 45) federal toll road 45D connecting the cities of Chihuahua and Ciudad Juárez the Copper Canyon rail route to and from Chihuahua and towns immediately on this route including Creel the road from Creel via San Juanito to San Pedro state highway 16 from San Pedro to Chihuahua There are high levels of organised crime activity, particularly human and drugs trafficking."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Sinaloa, except: the cities of Los Mochis and Mazatlán road 32 that runs between El Fuerte and Los Mochis the 15D federal toll road that runs the length of the state the Copper Canyon rail route to and from Los Mochis, El Fuerte and the towns immediately on this route Armed robbery and vehicle theft has happened in El Fuerte."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Tamaulipas, except: the border crossing at Nuevo Laredo accessed from Monterrey by federal toll road 85D – you should travel during daylight hours federal highways 80, 81 and 85 between Tampico, Ciudad de Victoria and Magueyes, and the entire area of Tamaulipas south of these highways Tamaulipas is dangerous due to the presence of many organised crime groups who fight for control of drug trafficking routes."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Zacatecas."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south-west of the road 45D."},{"form":"against all but essential travel","text":"advises against all but essential travel to the state of Michoacán, except the: city of Morelia accessed by federal toll roads 15D, 126 and 43; and the federal toll road 48D between the city of Morelia and the General Francisco Mujica airport town of Pátzcuaro accessed by federal toll roads 14D and 15 from Morelia, and boat trips out to islands on Lake Pátzcuaro federal highway 15D Michoacán is one of Mexico’s most violent states with high levels of organised crime and very little security presence."},{"form":"against all but essential travel","text":"advises against all but essential travel to the areas south and south-west of Lake Chapala to the border state of Colima, specifically the municipalities of: Acatlán de Juárez Amacueca Ameca Atemajac de Brizuela Atengo Atenguillo Atoyac Autlán de Navarro Ayutla Casimiro Castillo Chiquilistlán Cocula Cuautitlán de García Barragán Cuautla Ejutla El Grullo El Limón Gómez Farias Guachinango Juchitlán Mixtlán San Gabriel San Marcos San Martín Hidalgo Sayula Tapalpa Techaluta de Montenegro Tecolotlán Tenamaxtlán Teocuitatlán de Corona Tolimán Tonaya Tuxcacuesco Tuxcueca Unión de Tula Villa Corona Villa Purificación Zacoalco de Torres Zapotitlán de Vadill Zapotlán el Grande FCDO advises against all but essential travel to the northern municipalities of: Bolaños Chimaltitán Colotlán Hostotipaquillo Huejúcar Huequilla el Alto Mezquitic San Martin de Bolaños Santa Maria de los Ángeles Totatiche Villa Guerrero This is due to inaccessibility for security forces, lack of state control, drugs cultivation and high levels of violence between rival criminal groups."},{"form":"against all but essential travel","text":"advises against all but essential travel to the whole state of Colima, except the city of Manzanillo accessed by sea or by air via Manzanillo-Costalegre International Airport, and direct travel via road 200 from the airport to Manzanillo."}],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-19","page_updated":"2026-07-16T16:08:09+01:00"}},"timing":{"peak":"Dec-Apr (dry season; highest rates, biggest crowds)","shoulder":"May-Jun & Nov (~30-40% off, good weather)","green":"Jun-mid-Oct (hurricane/low; cheapest)","sargassum_window":"Apr-Aug (Jun-Jul peak); Playa moderate risk with barrier program","booking_window_lead_time":"peak 3-4 months; shoulder 4-6 months","holiday_event_peaks":["Christmas/New Year","Spring Break (Mar)","Semana Santa"],"fill_the_beds":"green/sargassum months pivot to cenote dives, Cozumel reef, Xcaret/Xplor parks, Fifth Avenue food+nightlife","campaign_start_trigger":"peak campaigns open Aug-Sep; shoulder ~3-4 months out"},"jewels":[{"name":"Cozumel reef wall (Palancar/Santa Rosa/Columbia)","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"World-class drift-wall diving on the Mesoamerican Reef, 40 min by ferry.","bookable_category":"dive excursion / liveaboard","source":"https://www.viator.com/Playa-del-Carmen/Cozumel/day-trips-d5501-d632","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"World-class drift-wall diving on the Mesoamerican Reef, 40 min by ferry.","when":"Dec-Apr","commission":"Amstar excursion 12% or dive-operator affiliate"},{"name":"Cenote cavern dive — Chikin-Ha / Dos Ojos","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Guided cavern dives with light beams and stalactites in the world''s longest cave system.","bookable_category":"cenote cavern dive (guide required)","source":"https://www.tripadvisor.com/Attractions-g150812-Activities-Playa_del_Carmen_Yucatan_Peninsula.html","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Guided cavern dives with light beams and stalactites in the world''s longest cave system.","when":"Dec-Apr","commission":"DMC excursion 12% / affiliate 4-8%"},{"name":"Xplor zipline + underground river","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"Mexico''s largest zipline circuit — 14 lines over 3.8 km plus amphibious buggies.","bookable_category":"eco-park adventure","source":"https://blog.xcaret.com/en/welcome-to-playa-del-carmen-mexico/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Mexico''s largest zipline circuit — 14 lines over 3.8 km plus amphibious buggies.","when":"Dec-Apr","commission":"Xcaret Agents / affiliate; park entry pass-through"},{"name":"Cobá + Tulum ruins day loop","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Cliff-top Tulum plus bikeable jungle pyramids at Cobá in one Maya day.","bookable_category":"guided cultural excursion","source":"https://www.amstardmc.com/en/destinations/mexico/tulum/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Cliff-top Tulum plus bikeable jungle pyramids at Cobá in one Maya day.","when":"year-round","commission":"Amstar 12%; ruin entry pass-through"},{"name":"La Casa de la Playa (Grupo Xcaret)","si_tag":"Romance & Honeymoons","status":"live","tier":"ultra","hook":"AAA Five-Diamond luxury on the Xcaret estate with private park access.","bookable_category":"luxury all-inclusive resort","source":"https://www.travelagentcentral.com/your-business/grupo-xcaret-launches-xcaret-agents-pro-booking-tool","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"AAA Five-Diamond luxury on the Xcaret estate with private park access.","when":"Dec-Apr","commission":"Xcaret Agents Pro — 15% auto-paid at check-out"}],"faq":[{"q":"What''s the real risk to plan for in Playa del Carmen?","a":"Sargassum, weather and water — not violent crime against tourists. 2026 is a record-forecast sargassum year, but Playa is moderate risk thanks to active municipal cleanup and a 5-km double-barrier program, with landings in pulses. Drink bottled water, use repellent for dengue (peak May–Nov, no malaria), and note hurricane season runs June–November.","source":"deeparrival.com / cdc.gov, 2026-07-04","si_tag":"safety"},{"q":"Can I dive Cozumel and the cenotes from Playa del Carmen?","a":"Yes — Playa is the best mainland dive base for both. Cozumel''s drift-wall reef (Palancar, Santa Rosa, Columbia) is a 40-minute ferry away at ~US$32 round trip, and cenote cavern dives sit under 30 minutes inland. Cozumel walls are drift dives for a reputable operator; cenotes are guide-required and weather-independent.","source":"viator.com / tripadvisor.com, 2026-07-04","si_tag":"diveglobal"},{"q":"What is there to do on Fifth Avenue?","a":"Fifth Avenue (Quinta Avenida) is the Riviera Maya''s densest dining and nightlife strip — a multi-kilometre pedestrian street of tacos-to-rooftop bars parallel to the sand. It is the town''s social spine, best on a weekday evening before the crowds; guided food-and-rooftop crawls are the easy way to graze it.","source":"tripadvisor.com, 2026-07-04","si_tag":"entertainment","si_fold_note":"folded from the retired `nightlife` slug into Global Live Entertainment 2026-08-23; the content is kept, the retired slug is not"},{"q":"Are the Xcaret and Xplor parks worth it, especially for families?","a":"Yes — they are the region''s marquee eco-parks. Xcaret runs cenotes, underground rivers and Maya performances; Xplor has Mexico''s largest zipline circuit (14 lines over 3.8 km) plus amphibious buggies. Park admission (~US$85–110 at Xcaret) is pass-through, and both sit just outside town — a full family day out.","source":"blog.xcaret.com, 2026-07-04","si_tag":"expedition"},{"q":"Can I visit Maya ruins from Playa del Carmen?","a":"Yes — it is the corridor''s best ruins base. Tulum''s cliff-top ruins and Cobá''s bikeable jungle pyramids pair in one day loop, and Chichén Itzá is a longer day trip; early morning (Nov/Feb) is best. Amstar and other DMCs run guided excursions, with ruin entry as a pass-through cost.","source":"amstardmc.com, 2026-07-04","si_tag":"culture"},{"q":"Where''s the best luxury for a honeymoon near Playa del Carmen?","a":"The Mayakoba estate and La Casa de la Playa. Mayakoba (Rosewood, Banyan Tree, Andaz) is a gated 595-acre lagoon estate of Virtuoso-affiliated flagships; La Casa de la Playa (Grupo Xcaret) is a 63-suite AAA Five-Diamond boutique ranked #1 Resort in Mexico for 2025. Both are ultra-tier honeymoon addresses on Playa''s doorstep.","source":"jetsetchristina.com / virtuoso.com, 2026-07-04","si_tag":"romance"},{"q":"When is the best time to visit Playa del Carmen?","a":"November–March is the dry, cooler high season (best weather, highest rates); May–October is hot, humid and rainy at the cheapest rates. The value sweet spots are the May–June and November shoulders at ~30–40% off, with November landing clear of sargassum and ahead of the holiday surge.","source":"machupicchu.org / travelswithelle.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Playa del Carmen Travel Guide 2026 — Cenotes, Cozumel Diving & Fifth Avenue | TravelWell.World","meta_description":"Plan Playa del Carmen: cenote diving, the 40-minute Cozumel reef ferry, Fifth Avenue nightlife, Xcaret parks, plus straight 2026 sargassum, Level 2 safety and dive-chamber info.","slug":"playa-del-carmen-mexico","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04","search_language":["en","es-MX"],"local_keywords":["qué hacer en Playa del Carmen","cenotes cerca de Playa del Carmen","ferry a Cozumel desde Playa del Carmen","mejor época para visitar Playa del Carmen 2026","sargazo Playa del Carmen 2026","buceo en cenotes Playa del Carmen","Quinta Avenida Playa del Carmen"],"hreflang":["en","es-MX"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"expedition","status":"live"},{"si":"diveglobal","status":"future"},{"si":"culture","status":"future"}],"ultra":[{"name":"Rosewood Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Banyan Tree Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Andaz / Alila Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Fairmont Mayakoba","price_tier":"luxury","virtuoso":false,"earning":"on application / host AOR","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"La Casa de la Playa (Grupo Xcaret)","price_tier":"ultra","virtuoso":true,"earning":"15% via Xcaret Agents Pro OR host-Virtuoso ($100 credit)","mor_posture":true,"source":"https://www.virtuoso.com/hotels/16561922/la-casa-de-la-playa"}],"source_verified":"2026-07-04","hero":{"query":"Playa del Carmen, Mexico"},"geo":{"lat":20.6296,"lng":-87.0739}}'::jsonb, 25),
